'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["sl"]={"g-flurpruefung":["Kaj vključuje vizualni in funkcionalni pregled pred začetkom dela?","Pred prvo misijo dneva.","Preverite le nivo goriva in barvo vozila.","Preverite zavore, krmiljenje, vilice, pnevmatike in varnostne naprave v skladu z navodili za uporabo.","Izvedite poskusno vožnjo z dvignjenim tovorom.","Dnevni pregled vključuje varnostno pomembne dele in funkcije v skladu z navodili za uporabo."],"g-rueckhalt":["Kako se spopadate z obstoječim sistemom za zadrževanje voznikov?","Viličar ima obvezen zadrževalni sistem.","Uporabljajte ga pravilno med vožnjo.","Uporabljajte samo na neravnih tleh.","Izključite ga za kratke vožnje.","Predvidene zadrževalne sisteme je treba uporabljati v skladu z navodili proizvajalca; zagotavljajo posebno zaščito v primeru napitnine."],"g-mangelmelden":["Kaj velja za viličar s poškodovanimi vilicami?","Ko preverite, opazite očitno upognjen zob.","Če je mogoče, porazdelite obremenitev na druge zobe.","Do naslednjega servisa vozite samo lahke tovore.","Viličarja ne uporabljajte in okvaro prijavite odgovorni osebi.","Poškodovana oprema za dvigovanje tovora lahko odpove; Varnostno pomembne napake zahtevajo zaustavitev do razjasnitve."],"g-einweisung":["Preklopite na viličar z drugačnimi kontrolami. Kaj je potrebno pred uporabo?","Delovanje se razlikuje od vašega prejšnjega vozila.","Navodila v zvezi z napravo in skladnost z navodili za uporabo.","Kratka razlaga nevpletenega sodelavca je vedno dovolj.","Ni dodatnih informacij, če imate dovoljenje za viličarja.","Splošna kvalifikacija ne nadomesti potrebnih navodil o napravi, ki se dejansko uporablja."],"g-anbaugeraet":["Uporabiti morate prilogo. Kaj najprej preverite?","Nova oprema spremeni način prevzema tovora.","Ali priključek ustreza homologaciji vozila in dovoljeni obremenitvi.","Le ali je napravo mogoče pritrditi vizualno.","Ali je priključek mogoče namestiti brez dokumentacije.","Priključki lahko spremenijo preostalo nosilnost in središče tovora; Preveriti je treba podatke o odobritvah in nosilnosti."],"g-diagramm":["Zakaj potrebujete diagram nosilnosti?","Prisotna je težka obremenitev s težiščem daleč navzven.","Za določitev najkrajše poti.","Za oceno največje dovoljene obremenitve glede na višino dviga in središče bremena.","Za določitev prostornine rezervoarja.","Dovoljene obremenitve so med drugim odvisne od razdalje bremena in višine dviga."],"g-lastschwerpunkt":["Kaj se običajno zgodi, ko se težišče premakne naprej?","Dolg tovor štrli daleč pred roglji vilic.","Dovoljena nosilnost se lahko zmanjša.","Nosilnost vedno narašča.","Razdalja nima vpliva na prevrnitveni moment.","Večja oddaljenost od težišča bremena poveča prevrnitveni moment in lahko zmanjša dovoljeno nosilnost."],"g-gabelabstand":["Kako naj vilice poberejo primerno paleto?","Želite pobrati enakomerno naloženo paleto.","Z zobmi čim bližje in le na enem vogalu.","S tako veliko razdaljo, da se paleta prevrne na stran.","S primernim razmikom med zobmi in zadostnim podvozjem ter podporno površino.","Tovor mora biti varno in čim bolj enakomerno podprt na vilicah."],"g-schieflast":["Tovor je nestabilno zložen. Kaj je prav?","Kartonske škatle lahko padejo, ko jih dvignete.","Začnite počasi; naboj se sam stabilizira.","Preden dvignete tovor, ga ustrezno zavarujte ali dajte ponovno sestaviti.","Breme dvignite nad višino glave, da vam ne bo v napoto.","Razsut ali nestabilen tovor lahko pade in ogrozi ljudi; najprej izvajajte varnostne ukrepe."],"g-personen":["Ali je mogoče človeka dvigniti na navadne vilice?","Kolega želi doseči luč.","Da, če sodelavec nosi čelado.","Ne, ljudje lahko uporabljajo le določene in dovoljene objekte v skladu s posebnimi zahtevami.","Da, če se približa le majhna višina.","Običajne vilice niso osebna delovna ploščad; Za prevoz in dvigovanje ljudi veljajo posebne zahteve."],"g-transporthoehe":["Kako običajno prevažate paleto?","Cesta je prosta in ravna.","Z dvignjenim bremenom le toliko, kolikor je potrebno in v skladu z navodili za uporabo.","Z dvignjenim bremenom čim višje, da se bolje vidi.","Z dvižnim drogom, nagnjenim močno naprej, ne glede na obremenitev.","Nizek transportni položaj zmanjšuje tveganje prevračanja in trčenja; Navodila za napravo so odločilna."],"g-kurvenfahrt":["Zakaj je hitro zavijanje z viličarjem nevarno?","Želite hitro zapustiti ozko pot.","Ker samo hitreje prazni baterijo.","Ker viličar samodejno bolje krmili.","Ker bočne sile vplivajo na stabilnost in lahko povzročijo prevrnitev.","Pri zavijanju pridejo v poštev dodatne sile; hitrost mora biti prilagojena obremenitvi in ​​razmeram."],"g-ladebruecke":["Kaj preverite, preden zapeljete na nakladalni most?","Moral bi se voziti v tovornjaku.","Le ali je pot videti dovolj široka.","Nosilnost, varna podpora in zaščita pred premikanjem ter zavarovanje vozila.","Samo, ali je razsvetljava prižgana.","Nakladalni mostovi in ​​vozila morajo biti zavarovani proti premikanju in primerni za tovor."],"g-fussgaenger":["Kako se obnašate v zmedenem križišču s pešci?","Vizualne povezave so omejene.","Vozite s primerno hitrostjo, po potrebi ustavite in zagotovite varno vidljivost.","Pri prenašanju tovora vedno zahtevajte prednost.","Samo trobi in vozi naprej.","Pešci potrebujejo posebno zaščito; Hitrost, vidljivost in komunikacijo je treba prilagoditi prometni poti."],"g-batterieladen":["Na kaj morate biti še posebej pozorni pri polnjenju pogonske baterije?","Uporablja se polnilna postaja za baterije.","Mesto polnjenja lahko izberete ne glede na navodila proizvajalca.","Odprti ogenj je dovoljen, dokler tovornjak miruje.","Primeren nakladalni prostor, zadostno prezračevanje in specifikacije proizvajalca ter zaščita pred požarom in eksplozijo.","Med polnjenjem lahko nastanejo nevarnosti zaradi električne energije, plinov in kemikalij; je treba upoštevati predvidene zaščitne ukrepe."],"h-beauftragt":["Pod kakšnimi pogoji smete samostojno upravljati dvižno delovno ploščad?","V podjetju bi morali uporabljati delovno ploščad.","Če imate vozniško dovoljenje.","Če ste primerni, poučeni ali usposobljeni in naročeni s strani delodajalca.","Če ste že kdaj videli delovno ploščad.","Delodajalec mora zagotoviti ustreznost, usposobljenost in razporeditev v skladu z operativnimi zahtevami."],"h-vorpruefung":["Kaj je treba preveriti pred začetkom dela z dvižno ploščadjo?","Oder je bil čez noč zunaj.","Vizualni in funkcionalni preizkus v skladu z navodili proizvajalca, vključno z varnostnimi napravami.","Samo barva in starost odra.","Ali je delovni material že na ploščadi.","Pred uporabo je treba stroj, krmilne elemente, zasilne funkcije in vidne poškodbe preveriti v skladu z navodili za uporabo."],"h-tragfaehigkeit":["Kateri podatek določa dovoljeno obremenitev delovne košare?","Dve osebi bi želeli s seboj vzeti dodatno orodje.","Ljudje lahko sami ocenijo dovoljeno skupno težo.","Šteje le teža najtežje osebe.","Specifikacija nosilnosti za ljudi, orodje in material ne sme biti presežena.","Nazivna obremenitev se nanaša na skupno dovoljeno obremenitev, vključno z morebitnim prevažanim materialom."],"h-untergrund":["Kaj upoštevate, preden postavite oder s podporami?","Delate blizu polnega območja.","Samo v dosegu roke.","Preverite nosilnost in ravnost podlage ter ustrezno podlago po navodilih.","Na najmanjšem možnem številu podaljšanih nosilcev.","Nezadostna podlaga ali neustrezna podpora lahko povzročita izgubo stabilnosti."],"h-wind":["Prihaja močan veter. Kako se lotite tega?","Znajdete se z zunanjim odrom.","Upoštevajte omejitve proizvajalca in če so prekoračene, zaustavite delovanje ali varno spustite košaro.","Platformo čim bolj razširite, da bo bolj stabilna.","Reagirajte le, če padejo razsuti predmeti.","Veter, ki ga dovoljuje proizvajalec, je omejitev uporabe; Veter lahko ustvari nevarne dodatne sile."],"h-strom":["Delati morate v bližini nadzemnega daljnovoda. Kaj je ključnega pomena?","Živa linija je v delovnem območju.","Čelada nadomešča vzdrževanje varnostne razdalje.","Samo izolirajte koš in delajte brez koordinacije.","Razjasnite nevarno območje in zagotovite potrebne zaščitne razdalje ali druge ustrezne ukrepe.","Električni preboj je možen tudi brez neposrednega kontakta; Pred začetkom obratovanja je treba določiti potrebne zaščitne ukrepe."],"h-notablass":["Zakaj je treba poznati postopek spuščanja v sili?","Možna je okvara običajnega nadzora.","Tako, da je v primeru okvare glede na napravo možno varno reševanje.","Tako, da naprava pri normalnem delovanju deluje hitreje.","Za nadomestitev rednega testiranja.","Pred uporabo je treba poznati in delovati krmiljenje v sili, spuščanje v sili in koncepte reševanja."],"h-gelaender":["Kako dosežete dodatno višino v delovni košari?","Montažna točka je tik izven vašega dosega.","Splezaj na ograjo košare.","Na ograjo postavite desko.","Uporabite primerno ploščad z zadostno delovno višino; ne plezajte po ograjah.","Plezanje po ograji ali improviziranih vzpetinah ogroža zaščito pred padcem."],"h-psaga":["Katere zahteve veljajo za osebno zaščitno opremo?","Uporabljate delovno ploščad, za katero je predviden zadrževalni sistem.","Vsako sidrišče zunaj košare vedno zadostuje.","Upoštevajte oceno tveganja, navodila proizvajalca in primerna sidrišča.","Ne uporabljajte nobenega varovala, če ima košara ograjo.","Ali in katera OZO je potrebna, se določi z oceno tveganja, konstrukcijo odra in navodili za uporabo."],"h-verfahren":["Ali je mogoče oder premikati z dvignjeno ploščadjo?","Delovno mesto je nekaj metrov stran.","Le če model in pogoji delovanja to dopuščajo po navodilih proizvajalca.","Vedno, dokler se vsi držijo.","Ne, nikoli, ne glede na obliko in odobritev proizvajalca.","Gibanje v dvignjenem položaju je odvisno od naprave in je dovoljeno samo v odobrenih pogojih delovanja."],"h-kollision":["Kaj je treba organizirati pri delu v bližini žerjavov ali drugih strojev?","Premični deli bi lahko dosegli delovno košaro.","Nič; delovna košara je vedno vidna.","Delovno košaro vedno vozite preko drugih strojev.","Uskladite delovna področja, da se izognete trkom ali stisnjenim točkam.","Hkratno delovanje stroja zahteva usklajene delovne procese in zaščito pred trki ali zagozditvami."],"h-einstieg":["Kako vstopite ali zapustite delovno košaro?","Košaro dosežete na ravni tal.","Preplezaj zunanjo ograjo.","Preko predvidenega dostopa v varnem položaju v skladu z navodili za uporabo.","Preko lestve, ki je postavljena zraven, z iztegnjeno roko.","Upoštevati je treba predviden dostop in navodila proizvajalca; Nenadzorovano plezanje čez predstavlja nevarnost padca."],"h-defekt":["Naprava za zaustavitev v sili ne deluje. kaj počneš","Napako boste odkrili med pregledom.","Ne uporabljajte platforme in prijavite napako.","Nadaljujte z delom, če normalne kontrole delujejo.","Zalepite stikalo, da ga nihče ne aktivira.","Okvara varnostne naprave je varnostno pomembna napaka in onemogoča varno delovanje."],"h-sicht":["Zaradi ovire ni mogoče videti premikanja med vožnjo. Kako se tega lotiš?","Moral bi premakniti mobilni oder.","Vozite počasi brez vidljivosti.","Samo zanašajte se na indikator razdalje.","Zaustavite gibanje in zagotovite vidljivost ali varna navodila v skladu z navodili za uporabo.","Pred posegom je treba varno pregledati ljudi, ovire in prometne poti."],"h-rettung":["Kaj vključuje načrtovanje namestitve pri delu na večjih višinah?","Oder se uporablja na oddaljenem območju.","Samo načrtovano trajanje dela.","Ustrezen koncept reševanja z dostopnimi, usposobljenimi ljudmi in postopki spuščanja v sili.","Predpostavka, da bodo gasilci morebitno težavo rešili takoj.","Učinkovito reševanje je treba organizirati vnaprej, tudi če običajni nadzor odpove."],"k-befaehigung":["Kaj je potrebno za samostojno upravljanje žerjava?","Delo na žerjavu naj bi prevzel nov sodelavec.","Ustreznost in zahtevana usposobljenost, navodila in pripadajoča naloga.","Zadostuje vozniško dovoljenje.","Enkratni ogled je dovolj.","Delo z žerjavom je dovoljeno zaupati samo usposobljenim in pooblaščenim osebam; Navodila za opremo so del tega."],"k-funktionspruefung":["Kaj je potrebno za pregled žerjava pred začetkom izmene?","Prevzamete notranji žerjav.","Samo preberite čas delovanja na ploščici z imenom.","Preverite varnostno pomembne funkcije in vidne napake v skladu z navodili za uporabo.","Preizkusite žerjav z največjo obremenitvijo brez preverjanja.","Obvezen obratovalni nadzor služi za zgodnje odkrivanje nevarnih okvar."],"k-traglast":["Kakšen je pomen dovoljene nosilnosti?","Tovor je treba dvigniti.","Gre za nezavezujoče priporočilo.","Velja le, ko je kavelj popolnoma uvlečen.","Dovoljena obremenitev za posamezne pogoje delovanja ne sme biti presežena.","Dovoljene obremenitve za nekatere vrste žerjavov so lahko odvisne od polmera, položaja ogrodja in oborožitve."],"k-personen":["Kaj velja za ljudi pod visečimi bremeni?","Tovor se premika po delovnem območju.","Nevarno območje mora biti prosto; nihče ne sme stopiti pod viseče breme.","Čelada vam omogoča, da ostanete neposredno pod njim.","Kratka prečkanja so dovoljena, če se dvigalo premika počasi.","Viseča bremena predstavljajo nevarnost padca in zmečkanin; Ljudje morajo biti izven nevarnega območja."],"k-signale":["Napadalca ne vidite in dobite nasprotujoče si signale. kaj počneš","Komunikacija je nejasna.","Nadaljujte z zadnjim ukazom vožnje.","Ustavite gibanje in jasno razjasnite komunikacijo.","Odložite tovor hitreje, brez posvetovanja.","Varni premiki tovora zahtevajo jasne signale in jasno komunikacijo."],"k-sicht":["Kdo bo nudil podporo med transportom, če žerjavist ne vidi v celoti poti tovora?","Steber dvorane zakriva pot.","Oseba, ki pride mimo brez predhodnega dogovora.","Nihče; pomembna je samo kljuka.","Primerna, poučena oseba z jasno dogovorjenim razumevanjem.","Če tovorna pot ni vidna, so potrebna ustrezna navodila ali druga varna rešitev."],"k-ruck":["Zakaj se je treba izogibati sunkovitim premikom žerjava?","Težko breme se začne nihati.","Ustvarjajo dodatne dinamične napetosti in lahko destabilizirajo obremenitev.","V bistvu zmanjšajo vsako gibanje nihala.","Vedno povečajo nazivno nosilnost.","Sile pospeševanja in zaviranja povečajo obremenitev žerjava in obes."],"k-sperrbereich":["Kaj morate preveriti, preden zanihate breme v skupnem prostoru?","Drugi zaposleni delajo v bližini.","Ali se tovor vizualno ujema z žerjavom.","Ali je nevarno območje zavarovano in ali ljudje niso ogroženi.","Ali je mogoče breme prenesti čim višje nad vsemi.","V vrtljivih in tovornih poteh ne sme biti nezaščitenih ljudi."],"k-stuetzen":["Kaj je ključnega pomena za avtodvigalo z oporniki?","Žerjav je postavljen na delno nasuta tla.","Samo širina ceste.","Barva podpornih plošč.","Nosilna podlaga ter podpora in porazdelitev obremenitve v skladu z navodili za montažo in proizvajalcem.","Namestitev pomembno vpliva na stabilnost, zlasti v spreminjajočih se razmerah tal."],"k-wetter":["Zaradi sunka vetra se tovor močno zamaje. Kaj je prav?","Delaš na prostem.","Varno ustavite gibanje in upoštevajte dovoljene delovne pogoje.","Hitro pospešite gibanje.","Nadaljujte z dvigovanjem bremena kljub prekoračitvi omejitev proizvajalca.","Veter in nihanje lahko destabilizirata tovor in žerjav; Upoštevati je treba omejitve uporabe."],"k-freileitung":["Kaj velja pri uporabi žerjavov v bližini nadzemnih električnih vodov?","Roka ali tovor bi se lahko približal črti.","Pri neprevodni obremenitvi so razmiki nepomembni.","Pred začetkom dela se z odgovornimi razjasnite o nevarnem območju in potrebnih zaščitnih ukrepih.","Zanašajte se le na lastno reakcijo upravljavca žerjava.","Obstajajo nevarnosti zaradi stika in napetosti; potrebne so varne zaščitne razdalje ali drugi ukrepi."],"k-sichern":["Kaj naredite, preden zapustite žerjav?","Delo je prekinjeno.","Tovor naj visi obešeno.","Pustite žerjav brez nadzora, medtem ko pogon deluje.","Varno spustite tovor in pritrdite žerjav v skladu z navodili za uporabo.","Visečih bremen ne smete pustiti brez nadzora; Žerjav in tovor morata biti varno parkirana."],"k-lastanschlag":["Kako veste, ali je uporabljena zanka ustrezna?","Tovor je treba dvigniti z dvižnim jermenom.","Glede na oznako, nosilnost, stanje in primernost za vrsto priključka.","Samo po barvi dvižnega traku.","Ker je bil že včeraj uporabljen.","Nosilnost in stanje morata biti zadostna ob upoštevanju pogojev pritrditve."],"k-stopp":["Oseba nepričakovano stopi na pot tovora. kaj počneš","Žerjav trenutno premika tovor.","Takoj varno ustavite gibanje in odstranite nevarno območje.","Samo dajte opozorilni signal in nadaljujte z vožnjo.","Dvignite tovor višje in ga zapeljite.","Ljudje morajo biti zaščiteni pred premiki bremena; Če obstaja neposredna nevarnost, je treba gibanje ustaviti."],"k-neuerkran":["Prejeli boste žerjav z neznanim krmiljenjem. Kaj je prav?","Kontrole so drugačne kot prej.","Če sumite, poskusite z običajnimi ključi.","Dovolite nekomu drugemu brez usposabljanja, da vozi naprej.","Pred samostojno uporabo prejmite potrebna navodila za napravo.","Celo izkušeni upravljavci žerjavov potrebujejo znanje o uporabljenih posebnih krmilnih napravah, zaščitnih napravah in omejitvah."],"a-kennzeichnung":["Kako veste dovoljeno nosilnost zanke?","Želite izbrati zanko.","Vonj materiala.","Na ustrezni, čitljivi oznaki nosilnosti in podatkih proizvajalca.","O dolžini skladiščenja.","Dovoljena nosilnost je določena z oznako in pogoji delovanja."],"a-sichtpruefung":["Opazite jasen rez v dvižnem traku. Kako se tega lotiš?","Trak naj bi nosil breme.","Ne uporabljajte traku in ga pošljite v testiranje ali zavrnitev.","Prekrijte rez s trakom.","Uporabljajte ga samo za posebej majhne obremenitve.","Poškodovane tekstilne zanke lahko odpovejo in jih je treba oceniti v skladu z merili za zavrženje."],"a-neigungswinkel":["Kaj se zgodi, če je kot naklona pramenov večji od navpičnice?","Obešalnik z dvema pramenoma se bolj razširi.","Sile pramenov se vedno zmanjšujejo.","Sile pramenov ostanejo enake.","Sile v pramenih se povečajo; Upoštevati je treba dovoljene kote in nosilnosti.","Ko se širina poveča, se poveča natezna sila na nosilno pramen."],"a-schwerpunkt":["Zakaj morate poznati težišče tovora?","Obremenitev se nabira neenakomerno.","Tako da tovor ob dvigovanju ostane stabilen in se ne prevrne nenadzorovano.","Za izbiro barve zank.","Da se lahko tovor hitreje vrti.","Neugodne pritrdilne točke ali položaj težišča lahko povzročijo prevračanje, zdrs ali nagnjena pobočja."],"a-kantenschutz":["Dvižni trak leži ob ostrem robu komponente. Kaj je treba narediti?","Komponento je treba dvigniti.","Hitro dvignite tovor, preden se jermen poškoduje.","Uporabite ustrezno zaščito robov in preverite vrsto pritrditve.","Tovorno površino čistite samo s krpo.","Ostri robovi lahko poškodujejo nosilna vlakna; opremo za obešanje je treba ustrezno zaščititi."],"a-haken":["Na kaj ste pozorni pri pripenjanju zanke?","Uporabljate tovorni kavelj.","Namestite zanko na stran konice kljuke.","Varnostna loputa naj bo stalno odprta.","Kavelj naložite, kot je predvideno, v dno kavlja in upoštevajte varnostne naprave.","Nedovoljena obremenitev konice trnka in nezavarovanost lahko privedeta do njegovega odpenjanja."],"a-knoten":["Ali lahko predolg dvižni trak skrajšate z vozlom?","Dolžina zaustavitve ne ustreza.","ne; Uporabljajte samo primerno, odobreno vrsto zanke ali primerno opremo za obešanje.","Da, če je vozel zelo močno zategnjen.","Da, dokler tovor trenutno miruje.","Vozli lahko znatno oslabijo tekstilne zanke in niso dovoljene improvizirane nastavitve dolžine."],"a-probehub":["Zakaj se breme na začetku dviguje previdno?","Želite varno prevažati.","Da se bo lahko čim hitreje odpravila na delo.","Za preverjanje položaja zank, stabilnosti in težišča.","Ker se nosilnost samodejno poveča.","Nadzorovan prvi hod pomaga zaznati nepravilne ustavitve in nestabilne položaje bremena."],"a-lastweg":["Kje se lahko ljudje zadržujejo med prevozom tovora?","Tovor se premika z žerjavom.","Neposredno pod bremenom z zaščitno čelado.","Na breme, če zdržijo.","Zunaj nevarnega območja in ne pod visečimi bremeni.","Tudi ob skrbni pritrditvi še vedno obstaja nevarnost padca ali nihanja bremena."],"a-haende":["Kako se izognete zmečkaninam med odstavljanjem?","Tovor se približa podporni površini.","Roke in noge držite stran od območja zmečkanja in uporabljajte ustrezne pripomočke.","Breme držite z golo roko.","Postavite se med tovor in steno, da popravite položaj.","Med bremenom in oporo nastanejo nevarne točke stiskanja."],"a-vierstraenge":["Kaj velja za porazdelitev obremenitve na štirinožnem vzmetenju brez kompenzacije obremenitve?","Togo breme je pritrjeno.","Vse štiri verige neizogibno nosijo enako količino.","Brez dokaza o enakomerni porazdelitvi se nosilnost ne sme uporabiti kot splošna ocena za štiri enako obremenjene pramene.","Kot naklona je takrat nepomemben.","Pri togih obremenitvah je možna neenakomerna obremenitev pramenov; To morata upoštevati konstrukcija in dovoljena nosilnost."],"a-chemikalien":["Kaj velja pri uporabi tekstilnih zank v stiku s kemikalijami?","Delate z neznano tekočino.","Barva traku zanesljivo dokazuje njegovo obstojnost.","Vsak tekstilni trak je odporen na vse kemikalije.","Preverite vzdržljivost in podatke o proizvajalcu; Ne uporabljajte neprimernih sredstev.","Kemikalije lahko napadejo zanke in neopaženo zmanjšajo njihovo nosilnost."],"a-aufbewahrung":["Kako so zanke shranjene po uporabi?","Misije je konec.","Čisto, suho in zaščiteno pred poškodbami v skladu s specifikacijami proizvajalca.","Obtičal na tleh pod nezaščitenim bremenom.","Na kakršen koli oster zunanji trnek.","Ustrezno shranjevanje preprečuje prezgodnjo obrabo in olajša vizualni pregled."],"a-auswahl":["Na kaj morate biti še posebej pozorni pri delu z občutljivimi ali ostrorobimi bremeni?","Pobarvan strojni del je treba premakniti.","Samo transportna hitrost.","Primerne zanke in zaščitni ukrepi za tovorno površino in robove.","Ne glede na obremenitev vedno ista jeklenica.","Vrsta pritrditve in material se morata ujemati z geometrijo, površino in nevarnostjo."],"a-abstimmung":["Žerjavist vas ne vidi. Kako dajete navodila?","Dodeljeni ste kot napadalec.","Poljubno mahate, dokler se ne začne gibanje.","Samo en klic pokličeš in odideš.","Prek jasno dogovorjenih znakov ali druge zanesljive komunikacije.","Napadalci in žerjavisti morajo jasno komunicirati; Če je nejasno, je treba gibanje ustaviti."],"b-qualifikation":["Kaj človek potrebuje za varno upravljanje hidravličnega bagra med delovanjem?","Dela na gradbišču naj prevzame nova oseba.","Ustrezne kvalifikacije, navodila v zvezi z napravo in zahtevana dodelitev.","Samo vozniško dovoljenje.","Samo hiter ogled operacije.","Delodajalec mora zagotoviti potrebno usposobljenost in operaterja ustrezno poučiti za nalogo."],"b-pruefung":["Kaj je vključeno v dnevni pregled stroja?","Prevzameš bager.","Preverite barvo laka in oblazinjenje sedežev.","Vizualni pregled in funkcionalni preizkusi v skladu z navodili za uporabo, na primer glede puščanja in poškodb.","Premikajte roko s polno hitrostjo, dokler se ne ustavi.","Poškodbe hidravlike, šasije in varnostnih naprav lahko povzročijo resne nesreče."],"b-leitungen":["Kaj je treba vedeti o podzemnih ceveh pred izkopom?","Moral bi izkopati jarek.","Samo okvirna globina predvidene izkopne jame.","Zadostuje barva nadzemnih markacij.","Pojasnite lokacijo možnih linij in določite ustrezne varnostne in raziskovalne ukrepe.","Če so cevi za elektriko, plin ali vodo poškodovane, so lahko smrtno nevarne."],"b-schwenkbereich":["Kako zaščitite ljudi v območju nihanja bagra?","Z roko pobirate material.","Ogradite ali zavarujte nevarno območje in oddaljite ljudi.","Pred vrtenjem lopato počasi premikajte.","Vozite čez območje nad glavami.","Vrtljiva nadgradnja in delovna oprema povzročata nevarnost zmečkanin in udarcev."],"b-boeschung":["Kaj je pomembno pri delu ob robu izkopane jame?","Bager stoji na utrjenem ali nasutem terenu.","Samo globina kopanja določa dovoljeno postavitev.","Bodite pozorni na nosilnost in pritrditev roba ter zahtevane razdalje glede na oceno tveganja.","Vozite čim bližje robu, da prihranite doseg.","Če ni dovolj oddaljenega prostora ali stabilnih tal, lahko brežina popusti in stroj lahko pade."],"b-standsicherheit":["Zakaj sta naklon in teren ključnega pomena za uporabo?","Gradbišče je na pobočju.","Stroj je enako stabilen na vseh površinah.","Podvozje na gosenicah odpravlja vsako nevarnost prevrnitve.","Neravnine in strmine lahko vplivajo na stabilnost; Upoštevajte omejitve uporabe.","Stabilnost in varnost pri prevrnitvi sta odvisni od tal, opreme, tovora in položaja stroja."],"b-wechselgeraet":["Kaj preverite po zamenjavi žlice bagra s hitro spojko?","Nameščen je bil nov priključek.","Ali je pravilno zaklenjen in zavarovan v skladu z navodili za uporabo.","Samo ali se barva lopate ujema.","Ali hidravlika deluje čim bolj tiho.","Okvarjene ključavnice lahko povzročijo padec priključkov."],"b-heben":["Na kaj moramo biti pozorni pri dvigovanju prosto visečega bremena z bagrom?","Bager se uporablja za dviganje.","Odločilna je le običajna sila kopanja.","Upoštevajte dovoljeno dvižno obremenitev, ustrezne pritrdilne točke in predpisane zaščitne naprave.","Tovor se lahko obesi na zobe žlice.","Dviganje je dovoljeno samo v predvidenih delovnih pogojih z ustrezno opremo."],"b-rueckwaerts":["Moraš vzvratno, pa ne vidiš poti. Kaj je prav?","Drugi delavci so v bližini.","Odpeljite previdno brez vidljivosti.","Samo trobi in vozi naprej.","Ustavite se, zagotovite vidljivost in nevarno območje ali organizirajte ustrezna navodila.","Vzvratna vožnja ne sme ogrožati ljudi; omejena vidljivost zahteva dodatne ukrepe."],"b-kabel":["Roka bi se lahko približala nadzemnemu daljnovodu. kaj počneš","Delaš na tesnem gradbišču.","Predhodno se z odgovornimi razjasnite o nevarnem območju in ustreznih zaščitnih ukrepih.","Ignorirajte črto, če je roka pobarvana.","Ročico premikajte le posebej hitro.","Električne nevarnosti nastanejo zaradi stika in preboja; potrebne so varne razdalje in zaščitni ukrepi."],"b-verlassen":["Kako parkirate bager pred odhodom?","Vzemite si odmor.","Pustite roko prosto plavati.","Varno odložite delovno opremo in zavarujte stroj pred premikanjem in nepooblaščeno uporabo.","Pustite motor prižgan in kabino odprto.","Spuščena delovna oprema in zaščita pred nenamernim premikanjem zmanjšata tveganje za nesreče."],"b-hydraulik":["Na poškodovanem vodu opazite hidravlično olje pod visokim pritiskom. Kaj je prav?","Vrvica pušča.","Z roko občutite puščanje.","Pritrdite novo objemko pod pritiskom.","Stroj varno zaustavite, pustite, da se tlak zniža, in poskrbite za popravila, ki jih opravi pooblaščeno strokovno osebje.","Hidravlična tekočina pod visokim pritiskom lahko povzroči resne poškodbe; nikoli ne preverjajte puščanja ročno."],"b-unterbau":["Kakšna je nevarnost vožnje po nestabilnih površinah?","Tla so po dežju mehka.","Stroj se lahko potopi, zdrsne ali prevrne.","Pogon samodejno postane širši.","Zaradi tega je območje vrtenja varnejše.","Nezadostna nosilnost lahko znatno poslabša stabilnost in varnost vožnje."],"b-arbeitsgeraet":["Ali lahko nekdo dela pod dvignjenim priključkom?","Človek želi nadzorovati nekaj pod lopato.","Da, ko motor teče v prostem teku.","Ne, ne brez zahtevane varne podpore in zavarovanja delovne opreme.","Da, če oseba nosi varnostno čelado.","Hidravlična oprema se lahko potopi; Vzdrževalna dela zahtevajo varno delovno opremo."],"b-geraeteart":["Preklopite s hidravličnega bagra na nakladalnik na kolesih. Kaj je potrebno?","Obnašanje delovanja in gibanja je drugačno.","Samo enaka obutev.","Testna vožnja brez navodil.","Kvalifikacija ali navodila, potrebna za nov tip stroja.","Kvalifikacija se mora ujemati z vrsto uporabljenega stroja in posebnimi operativnimi zahtevami."],"g-neigung":["Naložen viličar vozite po klancu. Kaj je pomembno?","Pot ima jasen naklon.","Tovor vedno vodite navzdol, tudi če je težak.","Tovor usmerjajte navkreber in upoštevajte delovna navodila za vožnjo po klancih.","Ne glede na smer vožnje dvignite vilice do maksimuma.","Na klancih in spustih je treba tovor vedno nositi navkreber; Upoštevati je treba vozila in navodila za uporabo."],"g-gabelabsenken":["Zakaj morajo biti vilice pri parkiranju spuščene?","Viličar je parkiran za odmor.","Da lahko drugi uporabijo vilice za vzpon.","Tako, da ostanejo vilice bolj vidne od daleč.","Da dvigovanje bremena ne predstavlja nepotrebnega tveganja za spotikanje ali poškodbo.","Spuščene naprave za dvig tovora zmanjšujejo nevarnost nesreč zaradi štrlečih ali nezavarovanih rogljev vilic."],"g-fahrerwechsel":["Kolega bi si rad izposodil viličar. Kaj mora biti prisotno?","Sodelavec ima od vas le ustno dovoljenje.","Imeti mora potrebne kvalifikacije in operativno pooblastilo.","Vaša lastna naloga samodejno velja tudi zanj.","Za vsako podjetje zadostuje vozniško dovoljenje za osebni avtomobil.","Neodvisno vodenje je vezano na osebno ustreznost, usposobljenost, usposobljenost in operativno razporeditev."],"g-ladungssicherung":["Paleta vsebuje razsute, zložene škatle. Kaj je prav?","Kartonska škatla lahko med vožnjo pade.","Pred transportom tovor zavarujte pred zdrsom in padcem.","Vozite le počasi na posebej neravnem terenu.","Zrahljane škatle nadomestite z višjim položajem vilic.","Pred transportom z viličarjem mora biti tovor stabilen in zavarovan pred padcem."],"g-bodenbelastung":["Pred vami je odeja z omejeno nosilnostjo. Kako se odločite?","Pot vodi čez vmesni nivo.","Pazite le na težo tovornjaka brez tovora.","Pojasnite dovoljeno obremenitev tal za viličarje in tovore.","Vozite z zagonom, da bo strop krajši čas obremenjen.","Pomembna je celotna dejanska obremenitev območja, vključno z vozilom, obremenitvijo in dinamičnimi vplivi."],"g-verkehrswege":["Pot vam prečka markirana pešpot. Kaj je prav?","Pešci imajo dostop do prehoda kadarkoli.","S hupo lahko vedno zahtevate prednost.","Preko markacije je dovoljeno zapeljati neopaženo.","Prilagodite hitrost, bodite pozorni na pešce in nadaljujte z vožnjo šele, ko je pot prosta.","Prometne poti je treba voziti upoštevajoč ljudi; Opozorilne table ne nadomestijo varne vidljivosti in proste poti."],"g-parkbremse":["Viličar parkirate na ravni podlagi. Kaj to vključuje?","Za nekaj minut želite zapustiti voznikov sedež.","Parkirajte, zategnite parkirno zavoro in zavarujte pred nepooblaščeno uporabo.","Vozilo pustite samo v nevtralnem položaju.","Pustite vilice v višini glave, da se jih nihče ne dotika.","Pred odhodom je treba viličar varno ustaviti in zavarovati pred nenamernim premikanjem."],"g-typenschild":["Kateri podatki so zavezujoči, ko gre za tovor na viličarju?","Hočeš pobrati težak stroj.","Ocenjena nosilnost glede na velikost vozila.","Podatki proizvajalca v diagramu nosilnosti ali nosilnosti.","Teža zadnje prepeljane palete.","Dovoljena obremenitev je določena s podatki proizvajalca in je med drugim odvisna od centra bremena in višine dviga."],"g-tore":["Z viličarjem se približaš nizkemu prehodu. Kaj preverjate?","Na vozilu je visok tovor.","Ali je prehod, vključno s tovorom in pritrditvijo, možen varno.","Samo višina nosilca vilic brez tovora.","Ali se lahko peljete skozi hitreje, preden se vrata zaprejo.","Pred prehodi je treba upoštevati čisto višino in širino ter dimenzije tovora in vozila."],"g-reifen":["Med dnevnim pregledom najdete močno poškodovano pnevmatiko. kaj počneš","Na pnevmatiki so vidne poškodbe, pomembne za varnost.","Vozite počasi do rednega servisa.","Povečate tlak v pnevmatikah in nadaljujete z vožnjo.","Ne vzamete vozila v obratovanje in ne prijavite škode.","Poškodovane pnevmatike lahko poslabšajo stabilnost in vodljivost; napako je treba razjasniti pred uporabo."],"h-absperren":["Zaposleni hodijo mimo pod vašo delovno ploščadjo. Kaj je potrebno?","Obstaja nevarnost padca orodja.","Ustrezen zaščitni ali prepovedani prostor pod delovnim mestom.","Samo obvestilo, ko greste prvič mimo.","Orodje shranjujte čim dlje od roba košare.","Delovno območje pod dvignjenimi delovnimi postajami mora biti zavarovano pred nevarnostjo zaradi padajočih delov."],"h-werkzeuge":["Kako prevažate orodje v delovni košari?","Na višini potrebujete več majhnih orodij.","Ohlapno jih postavite na ograjo, tako da so na dosegu roke.","Shranite in zavarujte tako, da ne padejo ali ovirajo delovanja.","Pritrdite na zunanjo stran ograje v žepu.","Ohlapni predmeti lahko padejo in ogrožajo ljudi; potrebno je varno shranjevanje."],"h-abstuetzung":["Na pokrovu jaška stoji nosilec. Kaj je treba preveriti?","Želite dvigniti platformo.","Prepričajte se le, da je pokrov suh.","Ali je mogoče obremenitev na tej točki varno prevzeti.","Ali drugih podpor ni treba uporabiti.","Podzemna in kontaktna območja morajo biti sposobna varno prevzeti podporne sile; Ovitke je treba oceniti ločeno."],"h-notaus":["Kdaj je treba uporabiti napravo za zaustavitev v sili?","Takoj se pojavi nevarno gibanje.","Samo ob koncu redne izmene.","Za zaustavitev v akutni nevarnosti v skladu z navodili za uporabo.","Kot nadomestilo za načrtovano znižanje.","Ustavitev v sili se uporablja za preprečevanje nevarnosti, ne običajni nadzor ali normalna zaustavitev."],"h-schraegstellung":["Odzove se opozorilo o nagibu odra. Kako reagiraš?","Stroj je na nagnjeni površini.","Na nizki delovni višini ne upoštevate opozorila.","Kljub opozorilu zapeljete v najvišji položaj dviga.","Oder zaustavite in spravite v varno stanje po navodilih proizvajalca.","Opozorila o nagibu lahko kažejo na neustrezno stabilnost; nadaljnji premiki ne smejo povečati nevarnosti."],"h-umgebung":["Kaj je potrebno organizirati pri postavitvi v bližini prometne površine?","Vozila se lahko dotikajo odra.","Zaščita pred naleti in ustrezno vodenje prometa.","Delovno košaro čim bolj zavihtite čez cesto.","Samo opozorilni klic pred zagonom.","Dvižne ploščadi morajo biti zaščitene pred trki z udeleženci v prometu; namestitev mora biti ustrezno zavarovana."],"h-ueberlast":["Sproži se opozorilo za preobremenitev v košari. kaj počneš","Povabljena so bila dodatna orodja.","Končajte delo pri višji hitrosti.","Določite dovoljeno obremenitev košare in upoštevajte specifikacije proizvajalca.","Trajno izklopite opozorilni signal.","Največja dovoljena obremenitev košare, vključno z ljudmi in materialom, ne sme biti presežena."],"h-quetschen":["Košaro zapelješ blizu pod streho. Katera nevarnost je posebej pomembna?","Nad košem je ostalo malo prostora.","Vpenjanje ali stiskanje med košaro in konstrukcijo.","Da motor porabi več goriva.","Da se smer vožnje vedno samodejno obrne.","Tesni prostori nad ali ob delovni košari lahko povzročijo resne zmečkanine."],"h-stromausfall":["Oder ostane na veliki višini brez glavnega pogona. Kaj je prav?","Običajna kontrola košare se ne odziva več.","Brez varnosti splezaš po roki.","Čakaš do konca svoje izmene, ne da bi bil obveščen.","Začnite pripravljeno reševanje z uporabo usposobljenih ljudi in spuščanjem v sili.","Za motnje je treba načrtovati varno reševanje; Usposobljene osebe morajo poznati funkcije v sili."],"h-transportstellung":["Kako pripravite teren za prevoz?","Dvižna ploščad se naloži na ustrezno vozilo.","Postavite roko in ploščad v transportni položaj v skladu z navodili za uporabo.","Platformo privežite čim dlje.","Pustite nosilce podaljšane, da zavzamejo več prostora.","Predpisani transportni položaj in pritrditev tovora temeljita na proizvajalčevih in transportnih specifikacijah."],"k-bremsprobe":["Kaj pokaže preizkus delovanja žerjavne zavore pred uporabo?","Želite biti sposobni varno držati tovor.","Ali se zavora ustavi in ​​zadrži gibanje, kot je predvideno.","Samo, ali osvetlitev kabine deluje.","Ali lahko kavelj samodejno drži tovor.","Pred uporabo je treba varnostno pomembne funkcije preveriti v skladu s specifikacijami."],"k-schraegzug":["Ali lahko z žerjavom vlečete bočni tovor pod kotom?","Kavelj ni navpično nad tovorom.","Da, če ima žerjav še rezervo tovora.","Ne, bremen se ne sme vleči z nedovoljenimi diagonalnimi vleki.","Da, če so zanke posebej kratke.","Diagonalno vlečenje lahko povzroči nenadzorovane premike in dodatno obremenitev žerjava in obes."],"k-verhakt":["Na podkonstrukciji visi tovor. Kaj je prav?","Pri dvigovanju se čuti upor.","Dvigujete, dokler ne pride stran.","Breme premikate sunkovito vstran.","Ustavite se in varno odstranite zaponko ali blokado.","Zagozdenih bremen ne smete trgati na silo, ker lahko nastanejo nesprejemljive sile."],"k-anzuheben":["Kaj preverite, ko prvič na kratko dvignete viseče breme?","Tovor se dvigne nekaj centimetrov od tal.","Ali visi v ravnovesju in je zaustavitev varna.","Ali se človek lahko postavi neposredno pod obremenitev.","Ali žerjav s hitrim obračanjem postane bolj stabilen.","Kratko nadzorovano dviganje se uporablja za preverjanje pritrditve, ravnotežja in varnega obnašanja tovora."],"k-lastweg":["Kje naj bo transportna pot tovora žerjava?","Več delovnih mest je pod možno potjo obremenitve.","Če je mogoče, nad zasedenimi delovnimi postajami.","Na načrtovani, jasni poti brez ogroženih ljudi.","Vedno diagonalno skozi najbolj prometno območje.","Tovorne poti morajo biti urejene tako, da viseči tovori ne ogrožajo ljudi."],"k-signalverlust":["Radijska povezava z maršalom se prekine. kaj počneš","Ne vidite same poti tovora.","Gibanje nadaljujete počasi.","Eksperimentalno zanihate v prejšnji smeri.","Gibanje ustavite, dokler ne pride do jasnega in varnega razumevanja.","Če ni komunikacije, se premikanje tovora morda ne bo nadaljevalo."],"k-haken":["Varnostni kavelj se ne zapira zanesljivo. Kaj je prav?","Med pregledom opazimo okvarjeno zapiralo.","Pred nadaljnjo uporabo je treba napako odpraviti strokovno.","Zaponko trdno zavežeš s kabelsko vezico.","Kavelj uporabljate samo za manjše tovore.","Okvarjene pritrdilne naprave na tovornih kavljih lahko povzročijo, da se zanke odpnejo in jih je treba popraviti."],"k-zugrichtung":["Kaj je pomembno za navpično oporo tovora?","Tovor je treba dvigniti s stroja.","Kavelj žerjava mora biti poravnan nad težiščem tovora.","Kavelj mora biti nameščen čim bolj postrani.","Pred dvigovanjem je treba breme potisniti.","Učinek sile, ki je čim bolj navpičen nad središčem obremenitve, preprečuje nedovoljene bočne sile in nenadzorovano nihanje."],"k-wartung":["Na žerjavu je opaziti nenavaden hrup brušenja. Kako se tega lotiš?","Hrup se pojavi pri dvigovanju.","Zakrijte hrup z večjo hitrostjo.","Varno ustavite operacije, prijavite napake in jih odpravite.","Nadaljujte z delom brez obvestila do odmora.","Opazne spremembe lahko kažejo na poškodbe, pomembne za varnost, in zahtevajo pregled."],"k-absetzen":["Kaj je treba zagotoviti pri spuščanju tovora žerjava?","Težko breme je nameščeno na površini.","Tovor lahko leži nepritrjen na nagnjeni površini.","Zanke se odstranijo, ko še lebdi.","Tovor je stabilen in zavarovan pred prevrnitvijo ali kotaljenjem.","Tovor se sme sprostiti iz obesnega orodja šele, ko je varno odložen in je vzpostavljena stabilnost."],"l-schwerpunkt":["Zakaj je treba pred udarcem poznati težišče?","Prevažati je treba stroj asimetrične oblike.","Tako, da ostane breme pri dvigovanju čim bolj uravnoteženo.","Tako, da lahko zanke izbiramo poljubno dolge.","Tako, da dovoljena nosilnost ne igra vloge.","Položaj težišča vpliva na porazdelitev bremena in varno ravnotežje pri dvigovanju."],"l-etikett":["Dvižni jermen nima berljive oznake nosilnosti. Kaj je prav?","Markacija je postala neprepoznavna.","Na podlagi barve ocenite nosilnost.","Dvižnega traku ne uporabljajte, dokler ni jasno dokazana njegova primernost.","Pri majhnih obremenitvah pas uporabite samo enkrat.","Za zanke so potrebne ustrezne oznake; Nepojasnjena nosilnost onemogoča varno izbiro."],"l-kantenschutz":["Prek ostrega jeklenega roba leži tekstilni trak. Kaj je potrebno?","Tovor ima ostre robove.","Brez zaščite povlecite trak čim tesneje.","Izvedite udarec hitreje.","Uporabite primerno zaščito robov ali drugo primerno opremo za obešanje.","Ostri robovi lahko poškodujejo ali prerežejo tekstilne zanke; potrebna ustrezna zaščita."],"l-spreizwinkel":["Kako večji kot naklona vpliva na obremenitev zank?","Breme dvignemo z dvema poševnima vrvema.","Pri manj ugodnih kotih se lahko sile v pramenih povečajo.","Sile pramenov izginejo.","Kot nima vpliva na napetost.","Pri manj ugodnem zaustavnem kotu se lahko povečajo sile na pramen; Upoštevati je treba tabele nosilnosti."],"l-knoten":["Ali je mogoče vrv za zanko poljubno skrajšati z uporabo vozla?","Vrv je predolga za načrtovano obremenitev.","Da, tesen vozel izboljša nosilnost.","Ne, uporabljajte samo odobrene metode krajšanja in sidranja.","Da, če je vozel pritrjen s trakom.","Nedovoljeni vozli oslabijo zanke in spremenijo njihovo dovoljeno nosilnost."],"l-zeichen":["Kaj velja za komunikacijo z osebo, ki upravlja žerjav?","Tovorna pot je delno zakrita.","Več ljudi daje različne signale hkrati.","Uporabljajo se jasni, predhodno dogovorjeni signali.","Z radijskimi žerjavi komunikacija ni nikoli potrebna.","Jasni znaki in jasne odgovornosti preprečujejo nevarne nepravilne premike."],"l-sichtpruefung":["Kdaj je treba zanke pregledati glede vidnih napak?","Želite uporabiti verigo za zanko.","Pred uporabo bodite pozorni na zunanje vidne poškodbe.","Le če se je nesreča že zgodila.","Samo enkrat ob prvem nakupu.","Pred vsako uporabo je treba oceniti varne delovne pogoje; Vidne poškodbe onemogočajo varno uporabo."],"l-drehung":["Dvignjeno breme se začne nenadzorovano vrteti. kaj počneš","Tovor se premika po tovorni poti.","Roko položite med tovor in steno.","Položiš se pod breme in se ga držiš.","Ohranjate razdaljo in pustite, da se gibanje kontrolirano ustavi.","Nenadzorovani premiki tovora povzročajo nevarnost zmečkanin in udarcev; Ljudje morajo zapustiti nevarno območje."],"l-ablegen":["Kdaj se lahko zanke odstranijo iz tovora?","Obremenitev je postavljena na nosilce.","Če je tovor stabilen in zavarovan pred prevrnitvijo ali kotaljenjem.","Takoj, ko se prvič dotakne tal, ne glede na položaj.","Medtem ko še vedno lebdite, da prihranite čas.","Zanke lahko odstranite šele, ko so varno in stabilno nameščene."],"l-ketten":["Verižna zanka ima močno upognjen člen. kaj počneš","Poškodbe so vidne že pred dvigom.","Poškodovano mesto ovijte z žico.","Odstranite verigo iz uporabe in jo dajte na strokovni pregled.","Breme dvignite le za polovico.","Deformirani členi verige so vidne poškodbe, ki lahko onemogočajo varno uporabo."],"b-einweiser":["Kaj je pomembno, ko je vidljivost iz bagra omejena?","Del stavbe zakriva vozniško območje.","Ustrezni vizualni ukrepi ali navodila in jasna komunikacija.","Samo pazi na kapuco.","Vozite skozi vrtljivo območje, čeprav ste nevidni.","Če je vidljivost omejena, je treba nevarnosti preprečiti z dodatnimi organizacijskimi in tehničnimi ukrepi."],"b-aushub":["Kje lahko skladiščimo izkop v bližini gradbene jame?","Rob jame ne sme biti dodatno ogrožen.","Nabirajte neposredno na rob, tako da dovozi ostanejo prosti.","Hraniti na dovolj varni razdalji in v skladu s specifikacijami gradbišča.","Postavite na ohlapno oporo brez nadaljnjega testiranja.","Izkopani material lahko zaradi dodatnih obremenitev ogrozi nasipe in podpore; Upoštevati je treba varnostne razdalje."],"b-personen":["Ali je dovoljeno, da se ljudje zadržujejo na območju nihanja, medtem ko se bager premika?","Oseba želi meriti med premikanjem.","Da, če nosi zaščitno čelado.","Da, če bager počasi niha.","Ne, nevarno območje mora biti prosto pred premikanjem.","V vrtljivem območju obstaja nevarnost hudih zmečkanin in udarcev; območje mora biti čisto."],"b-ladung":["Kako varno prevažate material z nakladalnikom na kolesih?","Po dvorišču je treba voziti napolnjeno lopato.","S primerno nizko transportno lego in prosto potjo.","Z dvignjeno lopato za boljšo vidljivost.","Z odprtimi vrati in močnim kotom krmiljenja.","Ustrezen transportni položaj zmanjša nevarnost prevračanja in izboljša stabilnost pri vožnji."],"b-anbaupruefung":["Kaj preverite po priključitvi priključka?","Priložena je bila nova lopata.","Samo čistoča laka.","Varno zaklepanje in delovanje v skladu z navodili za uporabo.","Le ali je naprava od zunaj videti enaka.","Nepravilne ključavnice na hitrih spojkah lahko povzročijo nenamerno sprostitev priključkov."],"b-einstieg":["Kako varno vstopiti v kabino bagra?","Stopnice so po dežju umazane.","Skozi roko splezajte v kabino.","Pojdite na gosenice v enem skoku.","Uporabite predvidene stopnice in ročaje ter očistite umazane stopnice.","Primerni vzponi in varna držala zmanjšujejo nevarnost zdrsa in padca."],"b-graben":["Stena jarka kaže razpoke in se ruši. Kaj je prav?","Delaš tik ob jarku.","Prekinite dela in naj odgovorni zavarujejo izkopno jamo.","Preprosto zapeljite bližje robu, da zaprete jarek.","Jarek dodatno poglobite brez zaščite.","Razpoke in premiki tal lahko kažejo na nestabilnost in zahtevajo dodatno oceno varnosti."],"b-betanken":["Na kaj ste pozorni pri dolivanju goriva v stroj za zemeljska dela?","Rezervoar je skoraj prazen.","Zavarujte motor in vire vžiga v skladu z navodili proizvajalca in preprečite razlitje.","Bencin ali dizel vedno natočite v kabini.","Kadite med točenjem goriva, ko ni vetra.","Požar in okoljske nevarnosti pri ravnanju z gorivom zahtevajo ustrezne zaščitne ukrepe."],"b-laufwerk":["Zakaj je treba gosenice in podvozje redno preverjati?","Med vožnjo opazite nenavadne vibracije.","Da se stroj lahko premika hitreje.","Ker lahko poškodbe vplivajo na varno vodenje in stabilnost.","Ker je delo vedno dovoljeno brez vizualnega pregleda.","Poškodba pogona lahko vpliva na manevriranje, stabilnost in varno delovanje."],"b-einweisen":["Kaj je potrebno pri delu v bližini javnega prometa za pešce?","Bager dela neposredno na robu pločnika.","Pešci naj se sami premikajo po nihalki.","Samo nalepite znak na lopato.","Učinkovito zavarujte nevarno območje in varno usmerjajte promet.","Tretje osebe ne smejo vstopiti v nevarno območje strojev za zemeljska dela; Potrebne so ustrezne ovire in usmerjanje prometa."],"g2-fahrweg":["Na cestišču je razlita tekočina. Kako se tega lotiš?","Viličar bi zapeljal neposredno čez spolzko območje.","Prenehajte z vožnjo in zavarujte ali odstranite nevarno mesto.","Z dvignjenimi vilicami čim hitreje zapeljite čez mesto.","Upajte na bolj suhe gume in nadaljujte z vožnjo nespremenjeno.","Onesnažene poti ogrožajo stabilnost, zato jih je treba pred vožnjo po njih ustrezno zavarovati."],"g2-sichtladung":["Visoka paleta zakriva pogled naprej. Kaj je prav?","Peljati se morate do skladišča in ne vidite poti.","Dvignite paleto, dokler ne vidite pod njo.","Vozite le z ustreznimi, varnimi metodami, kot je vzvratna vožnja z jasnim pogledom.","Še vedno se lahko vozite po cesti brez smerokaza ali jasnega pogleda.","Smer vožnje in preglednost morata omogočati varno opazovanje prometne poti; Tovor ne sme nadomestiti vizualnega pregleda."],"g2-fussgaengerstop":["Tik ob viličarju se ustavi pešec. kaj počneš","Oseba je znotraj možnega območja vožnje in vrtenja.","Pešca prehitite tako, da na kratko pospešite.","Peljite mimo osebe z dvignjenim tovorom.","Ustavite se in nadaljujte z vožnjo le na varni razdalji.","Ljudje se morajo izogibati nevarnemu območju; Če je treba, je treba potovanje prekiniti."],"g2-hubmast":["Opazite poškodovan hidravlični vod na stebru dvigala. Kaj velja?","Hidravlično olje vidno pušča iz priključka.","Izključite viličar in prijavite škodo.","Med dviganjem ročno preverite puščanje.","Manjša bremena dvigujte le do konca izmene.","Hidravlične poškodbe lahko povzročijo nenadzorovane premike; varna uporaba ni zagotovljena do testa."],"g2-lagerregal":["Paleto želite shraniti na polici. Kaj najprej preverite?","Raven polic je visoka in nosilnost je treba ohraniti.","Paleto čim hitreje potisnite na polico.","Preverite ustreznost predala, teže tovora in prostega prostora za shranjevanje.","Ocenite skupno težo izključno na podlagi števila škatel.","Police in oprema za prenašanje tovora se morajo ujemati s tovorom in skladiščnimi razmerami."],"g2-batterieschaden":["Akumulator viličarja je zunaj poškodovan. Kaj je prav?","Pred nakladanjem opazimo razpoke ali nenavadno tekočino.","Poškodbe prekrijte z lepilnim trakom in takoj naložite.","Naj druga oseba napolni baterijo, ne da bi jo preverila.","Ne polnite in ne uporabljajte ter obvestite odgovorne strokovnjake.","Poškodovane baterije predstavljajo električno in kemično nevarnost in zahtevajo strokovno oceno."],"g2-fahrerkabine":["Kaj velja za nepritrjene predmete v območju voznika?","Orodje je na tleh poleg kontrolnih pedalov.","Odstranite predmete in ohranite delovno območje prosto.","Med vožnjo držite orodje samo z eno nogo.","Skrijte ohlapne dele pod voznikov sedež.","Razrahljani predmeti lahko blokirajo pedala in ovirajo varno delovanje vozila."],"g2-uebergabe":["Viličar prevzamete po menjavi izmene. Kaj to vključuje?","Kolega je nazadnje uporabljal vozilo.","Predpostavimo, da je sodelavec prevzel vse preglede.","Opravite potreben pregled in se pozanimajte o znanih napakah.","Začnite pot brez pogleda na stroj.","Oseba, ki prevzema, se mora pred uporabo prepričati, da je v varnem stanju."],"g2-transportsicherung":["Visok predmet je ohlapen na paleti. Kako se obnašate?","Tovor se lahko pri zaviranju prevrne naprej.","Vilice nosite posebej visoko, da tovor ostane stabilen.","V ovinke peljite počasi, naravnost hitreje.","Tovor postavite na stabilen način in ga zavarujte pred prevrnitvijo ali padcem.","Razsuta bremena je treba pred transportom stabilizirati, da zaradi zaviranja in vožnje ne padejo."],"g2-arbeitsende":["Kaj je pomembno pri nenadzorovanem viličarju?","Končate izmeno in zapustite območje.","Vozilo varno parkirajte in ga zavarujte pred kotaljenjem in nepooblaščeno uporabo.","Pustite ključ, da bodo sodelavci našli stroj.","Pustite vilice v višini oči, tako da so vidne.","Varno parkiranje vključuje sprejem spuščenega tovora ter zaščito pred premikanjem in nepooblaščenim zagonom."],"g2-bremsweg":["Zakaj morate biti posebej pozorni na zavorno pot pod obremenitvijo?","Viličar prevaža težko blago skozi skladiščni hodnik.","Z velikim bremenom vedno zavirajte pozneje kot brez tovora.","Hitrost prilagodite vidljivosti, podlagi in obremenitvi.","Pri zaviranju močno dvignite tovor, da boste bolje upočasnili.","Masa in stanje ceste vplivata na pot ustavljanja; ključna je prilagojena hitrost."],"g2-rampe":["Kaj preverite, preden se povzpnete po strmi klančini?","Pot je morda prestrma za vozilo.","Vozite po klančini z največjo hitrostjo ne glede na naklon.","Zapeljite čez rob rampe z dvignjenim tovorom.","Preverite dovoljeni naklon in varen način delovanja iz specifikacij vozila.","Uporabljajo se lahko samo rampe znotraj predvidenih operativnih meja; Odločilna so navodila za uporabo in nadzor obremenitve."],"g2-zinke":["Paleta je širša od razdalje vilic. Kaj je treba upoštevati?","Načrtujete, da boste prevzeli nenavadno veliko breme.","Prilagodite razdaljo vilic in pritrdilne točke glede na tovor.","Če je tovor preširok, uporabite samo en zob.","Dvignite breme pod kotom, dokler ne doseže pravilnega položaja.","Enakomerna in ustrezna absorpcija obremenitev zmanjša zdrs in prevračanje."],"g2-betriebsanweisung":["Kakšno vlogo ima operativna prometna ureditev?","V skladišču veljajo označene enosmerne površine in površine za pešce.","Pri viličarjih veljajo samo pravila javnega prometa.","Upoštevajte določene poti in prometna pravila.","Ko je vozilo natovorjeno, ne upoštevajte oznak.","Poti podjetja in varnostna pravila ščitijo promet viličarjev in pešce."],"g2-nothalt":["Krmiljenje se nenavadno odziva med vožnjo. Kaj je prav?","Vozila ni več mogoče nadzorovati kot običajno.","Vozite pri višjih hitrostih, da bo krmiljenje bolj odzivno.","Izravnajte napako s posebno velikimi upogibi krmiljenja.","Ustavite se na varnem mestu in dajte vozilo na pregled.","Slabo krmiljenje ogroža varno vodenje; stroj ne sme nenadzorovano delovati naprej."],"g2-anschlagkette":["Z viličarjem želite premakniti prosto viseče breme. Kaj velja?","Tovor naj visi na kavlju pod vilicami.","Samo z odobreno napravo in primerno opremo za prenašanje tovora.","Vsaka veriga bo zadostovala, če tovor ni težak.","Verigo vpnite neposredno med obe vilici.","Prosto viseča bremena spremenijo stabilnost; Potrebna so dovoljenja proizvajalca in ustrezni objekti."],"g2-rollenlast":["Cilindrična komponenta leži nezavarovana na paleti. kaj počneš","Tovor se lahko med transportom kotali.","Posebej sunkovito se približajte paleti.","Zavarujte komponento pred kotaljenjem, preden prevzamete paleto.","Zobje postavite dovolj visoko, da komponenta ni vidna.","Okrogla ali kotalna bremena zahtevajo zanesljivo zaščito pred spremembami položaja."],"g2-pruefplakette":["Kako veste, ali je viličar uporaben?","Na stroju je prilepljena nalepka za pregled.","Vsaka nalepka vedno nadomesti dnevni vizualni pregled.","Pomanjkanje zračnosti je mogoče nadomestiti s previdno vožnjo.","Poleg preverjanja vozila je treba upoštevati veljavno stanje testiranja in odobritev delovanja.","Ponavljajoča se testiranja in dnevne operativne kontrole izpolnjujejo različne varnostne funkcije."],"g2-licht":["Razsvetljava v skladišču je nenadoma ugasnila. Kaj je prav?","Ne morete več varno videti ovir na poti.","Ustavite vožnjo, dokler ni zagotovljena varna vidljivost.","Povečajte hitrost vožnje, da zapustite temno območje.","Nadaljujte z vožnjo z dvignjenimi vilicami brez vizualnega pregleda.","Po poti, ki je ni mogoče varno spregledati, se ne sme voziti brez učinkovitih varnostnih ukrepov."],"g2-ueberhang":["Tovor sega daleč čez rob vilic. Kaj preverjate?","Paleto želite prepeljati skozi ozka vrata.","Izravnajte stransko projekcijo s hitro krivuljo.","Pred vožnjo ocenite oddaljenost, stabilnost in dovoljeno nosilnost.","Tovor vozite z največjo hitrostjo ne glede na njegovo obliko.","Previsi povečujejo tveganje trkov in lahko spremenijo stabilnost in potreben prometni prostor."],"g2-wartungsbereich":["Pred vzdrževalnim območjem so ovire. kako se obnašaš","Vaša običajna pot je začasno zaprta.","Na kratko premaknite ovire in neopazno zapeljite skozi.","Vozite neposredno skozi delovno območje pod obremenitvijo.","Upoštevajte zaporo in izberite odobreno alternativno pot.","Brez dovoljenja ni dovoljeno vstopiti v zaprta območja ali se skozi njih voziti."],"g2-bremsprobe":["Kdaj je smiseln preizkus delovanja delovne zavore?","Pred delom pripravite viličar.","Kot del obveznega pregleda pred uporabo.","Izvedite le po hudi nesreči.","Samo, če je tovornjak že dosegel visoko hitrost.","Pred uporabo se preveri delovanje varnostno pomembnih objektov."],"g2-fahrzeuganhaenger":["Želite vleči prikolico z viličarjem. Kaj je potrebno?","Podjetje načrtuje prevoz s pripetim tovorom.","Vsako prikolico brez preverjanja privežite na vilice.","Upoštevajte dovoljenje proizvajalca, ustrezno spojko in dovoljeno natezno obremenitev.","Samo povečajte tlak v pnevmatikah in odpeljite.","Vožnja vlaka je varna le v okviru tehničnih specifikacij in z ustrezno povezavo."],"g2-rueckfahrt":["Kaj je pomembno pri vzvratni vožnji z viličarjem?","Na hodniku skladišča je zmeda.","Vedno glejte samo v vzvratno ogledalo, ne glede na okolico.","Vozite brez vidljivosti, dokler enkrat pritisnete hupo.","Varno opazujte pot in območje ljudi ter jih po potrebi poučite.","Vzvratna vožnja zahteva jasen pogled ali učinkovite dodatne varnostne ukrepe."],"g2-lastentnahme":["Z visoke police vzamete paleto. Kaj je prav?","Paleta morda ni na sredini.","Tovor varno dvignite in ga stabilizirajte, preden ga spustite.","Pustite, da se paleta, ko jo izvlečete, obrne vstran.","Preverite pod dvignjeno paleto, da vidite, ali je poškodovana.","Nadzorovano dvigovanje in spuščanje preprečuje padanje tovora in nevarne premike."],"h2-absenkweg":["Zakaj mora območje pod dvižno delovno ploščadjo ostati prosto?","Košara se spusti in pod njo se položi material.","Pritisnite materiale navzdol s košaro.","Pazite le na predel stopala operaterja.","Izogibajte se nevarnosti zmečkanin in trkov med spuščanjem.","V območju spuščanja ne sme biti ljudi ali ovir, ki bi se lahko ukleščile."],"h2-transporthoehe":["Kako premaknete mobilni oder čez nizek prehod?","Razdalja je nižja kot pri podaljšani roki.","Platformo postavite v primeren transportni položaj v skladu z navodili za uporabo.","Pustite roko iztegnjeno in se pomaknite pod strop.","Košaro pritisnite ob stran okvirja vrat.","Pri premikanju se morata skupna višina in transportni položaj ujemati s specifikacijami proizvajalca in prehodom."],"h2-bodenoeffnung":["V tleh ob odru je nezavarovana odprtina. Kako reagiraš?","Vozna ali podporna točka se nahaja v bližini odprtine.","Namestite oporo neposredno na rob odprtine.","Zamenjajte mesto namestitve ali dajte strokovno preveriti nosilnost in pritrditev.","Nevarno mesto prekrijte le s kartonsko škatlo.","Odprtine in robna območja se lahko porušijo pod nosilnimi obremenitvami in jih je treba učinkovito upoštevati."],"h2-rettungsperson":["Zakaj mora biti druga oseba seznanjena s postopkom reševanja?","Operater lahko na vrhu postane nezmožen.","Tako da lahko delo v košarici praviloma poteka brez varovanja.","Tako, da lahko oder deluje hitreje, kot je dovoljeno.","Da se lahko v nujnih primerih začne varno reševanje.","Koncept reševanja mora upoštevati zemeljsko pomoč v primeru okvare ali nevarnosti."],"h2-werkzeugabwurf":["Kaj velja za orodja na visoki nadmorski višini?","Razrahljano orodje lahko pade čez rob košare.","Orodje zavarujte tako, da nikogar ne ogroža ali pade.","Preprosto postavite orodje na ograjo, da zmanjšate obremenitev.","Po potrebi vrzite orodje iz košare.","Padajoči predmeti ogrožajo ljudi spodaj; Material mora biti varno shranjen."],"h2-trittstufe":["Škatla naj služi kot dodaten stojni prostor v košari. Kaj je prav?","V nasprotnem primeru boste komaj prišli do delovnega mesta.","Postavite škatlo na ograjo in splezajte nanjo.","Ne plezajte na improvizirane vzpetine; Uporabljajte primerno delovno opremo.","Namerno naložite košaro čez dovoljeno višino.","Improvizirane višine poslabšajo predvideno zaščito pred padci in niso dovoljene."],"h2-lastverteilen":["Na kaj ste pozorni, ko je v delovni košari več ljudi?","Dve osebi delata v košari s težkim orodjem.","Obremenitev presodite izključno na podlagi velikosti orodja.","Težko orodje shranjujte neposredno na zaščitni ograji.","Ne prekoračite dovoljene obremenitve košare, vključno z ljudmi in orodjem.","Dovoljena nosilnost vključuje vse osebe, materiale in orodja v košari."],"h2-abstuetzplatte":["Kdaj pridejo v poštev dodatne podložke za podpore?","Montažna tla lahko prenesejo le omejeno obremenitev.","Če je to potrebno za varno porazdelitev obremenitve v skladu s specifikacijami.","Da bi podpore postavili čim bližje robu gradbene jame.","Za uporabo daljšega dosega brez podatkov o proizvajalcu.","Za varne podporne sile je potrebnih dovolj kontaktnih površin."],"h2-baugrube":["Oder naj bo nameščen neposredno ob robu gradbene jame. Kaj preverjate?","Podzemna podlaga bi lahko popustila bočno zaradi izkopne jame.","Podaljšajte podpore v izkopno jamo.","Zagotovite zadostno varnostno razdaljo in nosilnost podlage.","Tveganje nadomestite le s počasnim dvigovanjem košare.","Izkopne jame lahko vplivajo na stabilnost zaradi pobočij in zloma podtalja."],"h2-witterung":["Med uporabo se nabira led. Kako se obnašate?","Kontrolne površine in delovno območje postanejo gladki.","Dvignite oder, da se izognete snegu in ledu.","Ignorirajte opozorila, dokler je ploščad osvetljena.","Prekinite delo in ponovno ocenite pogoje delovanja v skladu z navodili za uporabo.","Spremembe vremena lahko spremenijo odgovornost, delovanje in varne meje uporabe."],"h2-aufbaukontakt":["Jeklena konstrukcija omejuje pot košare. Kaj je pomembno?","Pri dvigovanju obstaja nevarnost zmečkanin med košaro in nosilcem.","Načrtujte gibe tako, da vaše telo in košara ne ostaneta ukleščena.","Naj bo pot hitrejša, da bo košara hitreje šla mimo.","Konstrukcijo s košaro potisnite na stran.","Mesta stisnjenja med platformo in okoljem zahtevajo skrbno opazovanje in nadzorovano gibanje."],"h2-sicherheitsabstand":["Kdaj mora biti nevarno območje odra ograjeno?","Pod lokacijo poteka pot javnega prevoza.","Samo, če je predmet že padel.","Če bi lahko bile tretje osebe ogrožene zaradi premikanja ali padajočih predmetov.","Nikoli, saj delovna košara načeloma prepreči vse nevarnosti.","Območje pod in ob odru mora biti zaščiteno pred predvidljivimi nevarnostmi."],"h2-korbtor":["Kaj velja za vhodna vrata delovne kletke?","Ste že na delovni višini.","Pustite vrata odprta, da boste lahko hitreje prišli ven.","Z vrvjo privežite vrata za vedno odprta.","Vrata naj bodo zaprta v skladu s priloženim zaklepnim mehanizmom.","Priložene ključavnice so del zaščitnih ukrepov proti padcu iz delovne kletke."],"h2-energieleitung":["Kaj velja, če nadzemni vod ni varno izklopljen?","Delate z dvižno delovno ploščadjo blizu njih.","Zagotovite določene varnostne razdalje in potrebne zaščitne ukrepe.","Premaknite košaro tik pred črto, dokler se je ne dotaknete.","Zaupajte plastičnim gumam in delajte brez rež.","Električni preboji so možni tudi brez neposrednega stika; Potrebne so varnostne razdalje."],"h2-schwanken":["Delovna košara začne nenavadno močno nihati. Kaj je prav?","Gibanje ni več nadzorovano.","Ponovno se nenadzorovano prilagodite s hitrimi nasprotnimi gibi.","Ustavite premikanje in preverite vzrok ali pogoje delovanja.","Dodajte dodatne osebe v košarico, da bo ta težja.","Nenavadne vibracije lahko kažejo na neprimerne pogoje delovanja ali okvaro."],"h2-ladegeraet":["Polnilni kabel za električno vodeno stopnjo je poškodovan. kaj počneš","Pri priklopu je vidna poškodovana izolacija.","Dotaknite se poškodbe z mokrimi rokavicami.","Vtič čim močneje pritisnite v vtičnico.","Ne začnite postopka polnjenja in dajte kabel na strokovni pregled.","Poškodovana električna napeljava predstavlja nevarnost električnega udara in požara."],"h2-gelaenderanbau":["Ali lahko sami odstranite ograjo, da se približate?","Komponenta preprečuje, da bi se ljudje približali delovišču.","Zaščitnih naprav ne spreminjajte ali odstranjujte sami.","Po dvigu odvijte ograjo in jo namestite kasneje.","Nadaljujte z delom brez ograje, dokler nekdo stoji ob njej.","Strukturnih zaščitnih naprav ni dovoljeno spreminjati brez dovoljenih specifikacij in ukrepov varne zamenjave."],"h2-lastkran":["Ali se ploščad lahko uporablja kot žerjav za dvigovanje bremena?","Material naj se prevaža prosto obešen ob delovni košari.","Kadarkoli je teža manjša od vaše lastne telesne teže.","Samo, če proizvajalec in oprema izrecno dovoljujeta to posebno uporabo.","Preprosto pritrdite kavelj na ograjo in dvignite material.","Dvižne delovne ploščadi niso samodejno zasnovane za delo z žerjavom ali dodatnimi visečimi bremeni."],"h2-arbeitsvorbereitung":["Kaj vključuje priprave na novo lokacijo?","Gradbišča še ne poznate.","Samo ocenite razdaljo do najbližjega parkirišča.","Ne glede na okolico ga takoj popolnoma razširite.","Ocenite nevarnosti, zemljo, prometne poti, reševanje in ustreznost opreme.","Ocena tveganja glede na lokacijo je predpogoj za varne pogoje delovanja."],"h2-kabelschlaufe":["Napajalni kabel leži čez pot odra. Kaj je prav?","Med premikanjem se lahko kabel uklešči.","Očistite cestišče in zaščitite električne kable pred poškodbami.","Kabel s kolesi uporabite kot cestni prag.","Dvignite košaro, ne da bi preverili površino tal.","Kabli, ki jih povozite ali zmečkate, lahko povzročijo električne in mehanske nevarnosti."],"h2-leitungsnaehe":["Kdo pojasnjuje zaščitne ukrepe na električnem sistemu?","Platforma bi morala delovati v bližini opreme v živo.","Oseba v košarici odloča izključno na oko.","Vključite pristojne in izvajajte usklajene zaščitne ukrepe.","Razdalja bo določena šele po začetku dela.","Delo v bližini električnih sistemov zahteva načrtovane in usklajene zaščitne ukrepe."],"h2-funkkommunikation":["Zakaj morajo biti signali med podom in košaro jasni?","Oseba na tleh pomaga pri manevriranju.","Tako, da lahko več ljudi daje nasprotujoča si navodila hkrati.","Tako, da se zasilno spuščanje lahko preizkusi brez navodil.","Tako da se premiki izvajajo le po jasni komunikaciji.","Jasna komunikacija zmanjša nepravilne premike in trke pri manevriranju."],"h2-neuebedienung":["Preklopite na drugo vrsto odra. Kaj je potrebno?","Delovne funkcije se bistveno razlikujejo.","Navodila za posamezno napravo pred samostojno uporabo.","Samo branje logotipa podjetja na napravi.","Testna vožnja z že podaljšano košarico brez navodil.","Kvalifikacija sama po sebi ne nadomesti pouka o določeni vrsti naprave."],"h2-steckanschluss":["Kaj morate preveriti, preden priključite polnilnik?","Električno dvižno ploščad je treba napolniti.","Uporabite katero koli vtičnico, ne glede na stanje in varovalko.","Preverite ustrezno povezavo in nepoškodovan kabel v skladu z navodili proizvajalca.","Med polnjenjem redno izvlecite napajalni vtič.","Ustrezni in nepoškodovani električni priključki ščitijo pred električnim udarom in požarom."],"h2-absperrpersonal":["Med dvigovanjem oseba vstopi v ograjeno območje. kaj počneš","Osebo lahko vidite neposredno pod delovno košaro.","Nadaljujte z vožnjo, če oseba nosi zaščitno čelado.","Spustite orodje v njihovo smer kot opozorilni signal.","Ustavite nevarno gibanje in očistite območje.","Pregrada ne nadomesti opazovanja nevarnega območja med delovanjem."],"k2-arbeitsplanung":["Kaj je treba vključiti v pripravo na delo pred operacijo žerjava?","Tovor, lokacija in transportna pot še niso usklajeni.","Najprej dvignite najtežje breme brez nadaljnjega načrtovanja.","Na tleh dvorane označite samo najkrajšo pot.","Vnaprej razjasnite nosilnost, zanke, pot tovora in nevarno območje.","Načrtovan premik žerjava zahteva ustrezno ravnanje s tovorom, varne poti in usklajene zaščitne ukrepe."],"k2-hakenposition":["Kako je kavelj žerjava nameščen nad tovorom pred dvigovanjem?","Pritrdilne točke so pod žerjavom.","Čim bolj navpično nad težiščem glede na stop.","Odmaknjeno daleč vstran, da se tovor hitreje zaniha.","V vsakem primeru na zunanjem robu tovora, ne glede na težišče.","Navpična uporaba sile in ustrezne sidrne točke zmanjšajo stransko gibanje in nenadzorovane premike."],"k2-hakengabel":["Tovorni kavelj kaže opazno deformacijo. Kaj velja?","Kavelj je v primerjavi z običajnim stanjem videti upognjen.","Z naslednjo obremenitvijo upognite deformacijo nazaj.","Ustavite delovanje žerjava in naj kavelj pregleda strokovnjak.","Pritrdite le lahka bremena in nadaljujte z delom.","Deformacija lahko vpliva na varnost trnka; nepooblaščena nadaljnja uporaba ni dovoljena."],"k2-zugueberlast":["Breme je težje, kot se je sprva domnevalo. kaj počneš","Nove informacije o teži se pojavijo med pripravo.","Zamenjajte varnostno rezervo s hitrejšim dvigom.","Prezrite težo tovora tako, da ga pritrdite na drugo točko.","Določite dejansko obremenitev in ponovno preverite omejitve obremenitve.","Za varno dvigovanje so potrebni zanesljivi podatki o obremenitvi in ​​upoštevanje vseh ustreznih nosilnosti."],"k2-arbeitskorb":["Ali lahko navaden kavelj žerjava zlahka prevaža ljudi?","Človek želi priti na visoko delovno mesto.","Ne, potniški promet zahteva dovoljene posebne zmogljivosti in ukrepe.","Da, če se oseba drži za vrv zanke.","Da, takoj ko se udarec izvaja posebej počasi.","Prevoz oseb je dovoljen samo pod posebnimi pogoji, ki so za to določeni."],"k2-bruecke":["Mostni žerjav se premika po skupni poti dvorane. Kaj je pomembno?","Zaposleni ostanejo pod transportno potjo.","Vozite s tovorom tik nad glavami zaposlenih.","Učinkovito ohranjajte pot tovora in prometno območje prosta in varna.","Namesto nadaljnjih ukrepov uporabite le opozorilno hupo.","Ogrožene osebe ne smejo biti pod obešenimi bremeni ali na njihovi transportni poti."],"k2-zweitekrane":["Dva žerjava delata na prekrivajočem se območju. Kaj je potrebno?","Roke ali bremena lahko trčijo med seboj.","Oba žerjavista delata hkrati brez predhodnega dogovora.","Premiki so namerno pospešeni, da bi se izognili križiščem.","Koordinirati delovanje in sprejeti ustrezne ukrepe za preprečevanje medsebojnega ogrožanja.","Prekrivajoča se delovna področja zahtevajo usklajeno operativno organizacijo in ustrezne zaščitne ukrepe."],"k2-pruefbuch":["Kakšen je pomen obveznega periodičnega pregleda žerjava?","Stroj se redno uporablja v operacijah.","Obratovalni nadzor dopolnjuje s predpisanim strokovnim pregledom.","Trajno nadomesti kakršen koli vizualni pregled pred začetkom dela.","Potreben je samo po nesreči.","Ponavljajoči se pregledi in tekoči operativni nadzori imajo različne naloge."],"k2-absetzflaeche":["Predvideno območje namestitve je neenakomerno. Kako se obnašate?","Tovor bi se lahko prevrnil, ko bi bil nameščen.","Breme položite na en vogal in pustite, da visi nespremenjeno.","Pripravite ustrezne, nosilne in stabilne podlage ali površine.","Med spuščanjem postavite eno osebo pod tovor.","Območja za namestitev morajo varno podpirati tovor in preprečevati nevarno prevračanje ali kotaljenje."],"k2-anfahrbereich":["Preden se žerjav začne premikati, je v območju vožnje ena oseba. kaj počneš","Pot blokira oseba.","Osebo potisnite na stran s kratko testno vožnjo.","Odmaknite se samo z uporabo končnega stikala brez vizualnega pregleda.","Začnite premikati šele, ko je nevarno območje prosto in varno.","Vožnja in nihanje ne sme ogrožati ljudi."],"k2-schlaffseil":["Zakaj dvižna vrv ne bi smela postati nenadzorovano ohlapna, ko je odložena?","Tovor je, kavelj je še spuščen.","Da se vrv in kavlji ne zataknejo ali nenadzorovano obremenjujejo.","Tako, da lahko potem tovor bočno vleče vrv.","Tako, da se zanke same snamejo s kljuke.","Nenadzorovana napeljava kablov lahko privede do zapletov in nevarnih premikov bremena."],"k2-pendel":["Tovor, ki se prevaža, začne nihati. Kaj je prav?","Tovor se premakne bočno bolj, kot je bilo načrtovano.","Kompenzirajte s hitrimi nasprotnimi gibi in polno hitrostjo.","Zmanjšajte nadzorovano gibanje in umirite vožnjo brez ljudi v nevarnem območju.","Nihajočo obremenitev držite z golimi rokami.","Nihajoče obremenitve lahko vplivajo na ljudi in objekte; umirjeni gibi zmanjšajo tveganje."],"k2-funkakku":["Radijski nadzor žerjava ima šibko baterijo. Kaj velja?","Povezava se lahko med dviganjem zlomi.","Hitro dvignite breme, preden krmiljenje odpove.","Če je povezava prekinjena, premaknite tovor tako, da povlečete za zanko.","Pred uporabo zagotovite zanesljivo krmilno povezavo.","Zanesljiv nadzor in komunikacija sta predpogoja za nadzorovane premike žerjava."],"k2-mehrereanschlaeger":["Dva človeka istočasno dajeta različne signale žerjavistu. Kaj je prav?","Znaki si nasprotujejo.","Prekinite gibanje in razjasnite jasno odgovornost.","Dajte prednost znaku osebe, ki je bolj oddaljena.","Gibanje nadaljujte po lastnem občutku.","Vozniki žerjavov potrebujejo jasno in nedvoumno komunikacijo, zlasti kadar so tovorne poti nejasne."],"k2-endabschaltung":["Zakaj ne bi smeli končnega stikala zlorabiti kot običajne omejitve giba?","Tovor se pogosto premakne do največje dvižne razdalje.","Končna stikala na splošno omogočajo hitrejše dvigovanje brez vidnosti.","Končna stikala so varnostne naprave in ne nadomeščajo nadzorovanega delovanja.","Z vsakim udarcem jih je treba udariti čim močneje.","Varnostne naprave služijo za zaščito pred nevarnostmi in se jih ne sme pretiravati, kot je bilo načrtovano."],"k2-wetterbeobachtung":["Veter se znatno poveča z veliko površinsko obremenitvijo. Kaj je potrebno?","Velika površina komponent deluje kot jadro.","Breme vedno dvignite višje, da veter manj vpliva.","Zamenjajte zanke s tanjšimi.","Ocenite meje vetra in delovanja ter po potrebi prilagodite dviganje.","Veter lahko ustvari znatne dodatne sile in nihalna gibanja, zlasti pri obremenitvah velikih površin."],"k2-ortswechsel":["Kaj je pomembno pri selitvi avtodvigala na novo lokacijo?","Podtalje in podporni pogoji se spreminjajo.","Preverite lokacijo stojala in podporo, preden ponovno dvignete tovor.","Uporabite nastavitve s prejšnje lokacije brez preverjanja.","Med dviganjem naj se opora ponovno nastavi.","Vsako mesto namestitve ima lahko različne pogoje obremenitve tal in podpore."],"k2-betriebsbereich":["Čez cesto naj bi delal žerjav. Kaj je treba pojasniti?","V nevarno območje bi lahko prišle tretje osebe.","Cesto zavarujte le z opozorilno hupo.","Obvezne zapore, glasovanje in zaščitni ukrepi pred vozliščem.","Tovor čim hitreje dvignite nad vozila, ne da bi ga zavarovali.","Varno usmerjanje prometa preprečuje nepotrebno tveganje za tretje osebe zaradi tovora in premikanja žerjava."],"k2-hochheben":["Po preskusnem dvigu breme očitno visi ukrivljeno. Kaj je prav?","Fokus je bil očitno napačno ocenjen.","Nadaljujte z dvigovanjem, da se neravnovesje popravi.","Ena oseba naj vleče nagnjeno breme.","Tovor varno odložite in ponovno preverite pritrditev in težišče.","Testno dvigalo se uporablja za odkrivanje nepravilne pritrditve in nestabilnih položajev tovora pred transportom."],"k2-schwebelast":["Ali lahko pustite dvignjeno breme viseti brez nadzora?","Izmena se konča, tovor pa je še vedno na kavlju.","Ne, varno spustite tovor in pravilno pritrdite žerjav.","Da, če je žerjav zaklenjen proti premikanju.","Da, če je na tleh opozorilni znak.","Načeloma visečega bremena ne smemo puščati brez nadzora."],"k2-mitnahme":["Kolega se želi peljati na tovor žerjava. Kaj velja?","Tovor je treba prepeljati na višjo točko.","Jahanje je dovoljeno, če sodelavec nosi čelado.","Ljudje se ne smejo prevažati ali pritrditi na običajne tovore.","Vožnja je vedno dovoljena, dokler je sodelavec žerjavistu znan.","Prevažanje ljudi skupaj z bremeni predstavlja znatno tveganje padca in zmečkanin."],"k2-warnsignal":["Delujoči opozorilni sistem na žerjavu odpove. Kaj je prav?","Opozorila pred speljevanjem ni več mogoče zagotoviti.","Ignorirajte sistem, ko motor teče.","Trajno zamenjajte opozorilo s pritiskom na ohišje.","Prijavite varnostno napako in prekinite delovanje v skladu z navodili.","Zahtevane opozorilne naprave morajo delovati tako, da so ljudje pravočasno zaščiteni."],"k2-schneekante":["Mobilni žerjav mora biti podprt na zmrznjenih neravnih tleh. Kaj velja?","Tla lahko z odmrzovanjem izgubijo nosilnost.","Ocenite nosilnost in stanje podpore v dejanskih razmerah.","Zmrznjena tla imajo vedno kakšno nosilnost.","Podpore postavite samo na majhne kamne.","Temperatura, vlažnost in struktura podtalnice vplivajo na nosilnost lokacij žerjavov."],"k2-laufkatze":["Voziček se premika proti oviri. Kako se obnašate?","Na voznem območju je predmet.","Predmet z bremenom počasi potisnite stran.","Pravočasno ustavite gibanje in varno odstranite oviro.","Peljite mimo ovire s povečano hitrostjo.","Gibanje žerjava mora biti vodeno tako, da ne pride do trkov z ovirami."],"k2-anschlagaufnahme":["Tovor dvignite z nenamensko ušesco. Kaj je prav?","Ušesce je lahko bilo namenjeno samo za pritrditev pokrova.","Vsako uho je primerno za polno obremenitev žerjava.","Očesce naložite samo z dvema osebama hkrati.","Pred uporabo preverite nosilnost in primernost sidrne točke.","Vsako obstoječe ušesce ni stabilna pritrdilna točka za bremena žerjava."],"l2-seilbruch":["Žična vrv prikazuje več pretrganih posameznih žic. Kaj je prav?","Lomne točke so v območju nosilne vrvi.","Ne uporabljajte dvižnega orodja in ga dajte na strokovno oceno.","Z golimi rokami upognite konce žice nazaj.","Nadaljujte z uporabo vrvi, če je breme posebej majhno.","Pretrganje žice je lahko merilo za zavrženje; Poškodovane vrvi je potrebno strokovno oceniti."],"l2-schaekel":["Kaj je ključnega pomena pri uporabi okova?","Okov povezuje zanko in breme.","Zamenjajte vijak s poljubnim žebljem.","Preverite ustrezno nosilnost, nepoškodovano stanje in pravilne vijake.","Na podlagi barve ocenite nosilnost.","Okovja morajo biti primerno velika, uporabljena v celoti in v predvideni smeri nakladanja."],"l2-tragfaehigkeit":["Kaj morate upoštevati pri uporabi več pramenov?","Prameni potekajo pod kotom glede na navpičnico.","Enostavno seštejte nosilnost vsakega pramena po želji.","Breme obesite samo na najlažji pramen.","Upoštevajte nosilnost celotnega tipa sidra in kotnika.","Kot nagiba in efektivno število pramenov pomembno vplivata na dovoljeno obremenitev."],"l2-schweissnaht":["Ali je mogoče improvizirano sidrišče privariti na breme?","Za tovor ni določenih ustreznih prevzemnih mest.","Uporabljajte samo pravilno zasnovane in odobrene sidrne točke.","Zadošča vsak zvar brez testiranja.","Skozi odprtino v pločevini vstavite kavelj.","Sidrišča morajo biti dokazano primerna za sile, vključene v dviganje."],"l2-einseitig":["Tovor je na eni strani bistveno težji. Kako se tega lotiš?","Težišče je zunaj geometrijskega središča.","Pustite vse pramene enake dolžine ne glede na težišče.","Določite težišče in temu prilagodite položaj.","Najprej dvignite tovor na polno dvižno višino.","Če je težišče izven središča, se lahko bremena nepričakovano prevrnejo ali pa so posamezni prameni preobremenjeni."],"l2-kettenriss":["Kaj velja za verižno zanko z vidnimi razpokami?","V enem od členov verige je razpoka.","Označite razpoko z barvo in jo dvignite nespremenjeno.","Ovijte povezavo z žico in jo ponovno uporabite.","Takoj odstranite verigo in obvestite odgovorno osebo.","Razpoke v členih nosilne verige so poškodbe, pomembne za varnost, in zahtevajo razgradnjo."],"l2-lastfuehrung":["Kako prenašati velik tovor, ko obstaja nevarnost vrtenja?","Tovor lahko med dvigovanjem zaniha vstran.","Uporabljajte ustrezne usmerjevalne naprave in varno razdaljo.","Med vožnjo držite tovor neposredno med rokama.","Stopite pod tovor in ga poravnajte od spodaj.","Vodenje tovora ne sme povzročiti, da bi roke ali telesa zašli v nevarno območje."],"l2-schnueren":["Kaj je pomembno pri pritrjevanju vezalk?","Zanka je vodena okoli komponente.","Predpostavimo enako nosilnost kot katera koli druga vrsta sidra.","Upoštevajte ustreznost vrste priključka in dovoljeno obremenitev glede na oznako.","Orodje za zanko poljubno povlecite skupaj brez preverjanja.","Vrsta vezalke lahko spremeni dovoljeno nosilnost in jo je treba pravilno uporabljati."],"l2-winkelmesser":["Zakaj ne morete prezreti ravnega kota pramena?","Dve obesni vrvi potekata skoraj vodoravno glede na tovor.","Ravni kot samodejno naredi pramen močnejši.","Obremenitev je vedno enakomerno porazdeljena ne glede na kot.","Velike sile pramenov lahko presežejo dovoljeno nosilnost.","Ko se kot navpičnice poveča, se napetosti na pramenih povečajo."],"l2-heisse-last":["Kaj morate preveriti za vročo obremenitev?","Jekleni del je bil pred kratkim toplotno obdelan.","Upoštevajte temperaturne omejitve zanke in ustrezno izbiro.","Vsaka tekstilna zanka lahko prenese vse temperature.","Oznaka ni pomembna, ko je vroče.","Temperatura lahko vpliva na dovoljeno nosilnost zank."],"l2-abstand":["Ali lahko pod tovor položite prste, ko ga odlagate?","Tovor mora pristati na površini z milimetrsko natančnostjo.","Da, če nosite delovne rokavice.","Ne, vzdržujte razdaljo in uporabljajte ustrezne pripomočke.","Da, če je premikanje žerjava posebej počasno.","Deli telesa med tovorom in podlago se lahko ukleščijo."],"l2-verbindung":["Vezni člen verige zanke ni zaklenjen. Kaj velja?","Sponka manjka.","Uporabite zapah brez ključavnice, ko nihče ne gleda.","Element zalepite z lepilnim trakom.","Ne udarjajte, dokler pritrdilni element ni pravilno pritrjen.","Vezni elementi morajo biti zavarovani v celoti in v skladu z njihovo konstrukcijo."],"l2-lasthaken":["Kaj preverite, ko visite na kavlju žerjava?","V kavelj je treba voditi več zank.","Zagotovite varno prileganje in ustreznost kavljev in vzmetenja.","Na konico kljuke namestite zanke.","Ključavnico kljuke zamenjajte s kabelsko vezico.","Silo je treba uporabiti v predvidenih območjih."],"l2-fasern":["Dvižni trak kaže močno hrapavost in poškodbe vlaken. Kaj je prav?","Podporna vlakna so vidno poškodovana.","Poškodbo pokrijte z drugim vozlom.","Odstranite dvižni pas in ga dajte pregledati strokovnjaku.","Nato dvignite breme hitreje.","Poškodovana nosilna vlakna lahko bistveno zmanjšajo nosilnost dvižnega traku."],"l2-anheben":["Kaj velja takoj po prvem centimetru dviga?","Tovor se pravkar dvigne s podlage.","Brez nadzora povlecite breme do njegove polne višine.","Pod bremenom preverite, ali so zanke napete.","Preverite položaj zaustavitve, ravnotežje in obnašanje gibanja.","S kontroliranim testnim dvigom so morebitne nestabilnosti vidne pred nadaljnjim transportom."],"l2-lastgewichte":["Teža tovora ni znana. Kaj je prav?","Komponenta nima oznake teže.","Preden izberete zanke, določite nosilno težo.","Težo ocenite glede na barvo tovora.","Uporabite katero koli zanko dvojne dolžine.","Brez znane ali zanesljivo ugotovljene teže primernosti zank ni mogoče z gotovostjo preveriti."],"l2-lose-teile":["Na tovoru, ki ga je treba dvigniti, so razrahljana orodja. kaj počneš","Pri dvigovanju lahko orodje pade.","Med vožnjo držite orodje z eno roko.","Pred dvigovanjem odstranite ali učinkovito zavarujte ohlapne predmete.","Dvignite breme nekoliko hitreje, da vam kaj ne zdrsne.","Ohlapni predmeti lahko padejo in ogrozijo ljudi v okolici."],"l2-wind":["Pri močnem vetru je pritrjena velika obremenitev. Kaj velja?","Komponenta ponuja vetru veliko površino za napad.","Dvignite breme, ne da bi upoštevali nihanje.","Dodatni ljudje morajo neposredno držati tovor.","Ocenite vetrovne razmere in se vzdržite dvigovanja, če situacija ni varna.","Sile vetra lahko vplivajo na vodenje tovora in stabilnost med prevozom."],"l2-unterlage":["Zakaj so ustrezni dokumenti pomembni pri odstavitvi?","Okroglo breme bi se odkotalilo po tleh.","Tovor položite trdno navzdol in ga po potrebi zavarujte pred kotaljenjem.","Tovor pustite stati neposredno na zankah.","Dokumente potisnite pod tovor šele, ko jih odložite.","Ustrezne opore preprečujejo prevračanje in neželene premike pri odlaganju."],"l2-transportweg":["Kaj je treba uskladiti pred prevozom tovora?","Tovor se premika po več delovnih območjih.","Samo pričakovano trajanje vozlišča.","Varna tovorna pot, komunikacija in potrebne ovire.","Ena oseba naj pokaže pot pod tovorom.","Prevoz tovora zahteva varne prometne poti in jasno koordinacijo."],"l2-schutzschlauch":["Na kaj morate biti pozorni pri uporabi zank z zaščitno cevjo?","Trak leži ob grobem robu.","Vsaka tanka tkanina nadomesti ustrezno zaščito robov.","Zaščitna cev odpravi morebitno dovoljeno mejo obremenitve.","Izberite zaščitno opremo glede na primernost in zahteve uporabe.","Zaščitna oprema mora ustrezati materialu, robu in predvideni obremenitvi."],"l2-reinigung":["Dvižni jermen je bil onesnažen z neznano kemikalijo. Kaj je prav?","Traku ni več mogoče jasno oceniti.","Prenehajte z uporabo in strokovno razjasnite združljivost ali stanje.","Očistite s poljubnim topilom in takoj nadaljujte z dvigovanjem.","Ignorirajte kemikalijo, dokler je trak suh.","Kemikalije lahko vplivajo na trdnost tekstilnih zank."],"l2-aufhaengung":["Kaj preverite za več pramenov na obešalnem členu?","Dva pramena sta nameščena skupaj v suspenziji.","Pramen se lahko poljubno premakne v konico kljuke.","Vsi povezovalni elementi morajo biti primerni in razporejeni tako, kot je predvideno.","Obroč z razpoko se lahko uporablja za majhne obremenitve.","Omejevalni in vezni elementi morajo biti nosilni in pravilno nameščeni."],"l2-einweiserrolle":["Kaj velja, če napadalec in žerjavist nimata vidnega polja?","Nosilec blokira pogled na spustno točko.","Koordinirajte s klicanjem več ljudi brez odgovornosti.","Premaknite breme na podlagi hrupa brez navodil.","Organizirajte jasno, varno komunikacijo in jo prekinite, če je nejasna.","Pomanjkanje vidnosti je treba nadomestiti z učinkovito koordinacijo in varno komunikacijo."],"l2-ausserbetrieb":["Poškodovana zanka je bila urejena. Kaj je še pomembno?","Ostaja prosto dostopen skupaj z viri, pripravljenimi za uporabo.","Zavarujte pred nadaljnjo nenamerno uporabo in obvestite odgovorno osebo.","Izdelek vrnite neoznačen v zalogo.","Ponovno ga uporabite samo, ko nosite posebej majhen tovor.","Zavržene zanke je treba pred nadaljnjo uporabo zanesljivo zaščititi."],"b2-schwenkradius":["Zakaj je radij zadnjega nihanja bagra kritičen?","Rep se premika po omejenem delovnem območju.","Nihajna nadgradnja lahko ujame tretje osebe.","Radij nihanja nima vpliva na osebe ob stroju.","Zadnji se vedno premika samo v smeri vožnje.","Pri vrtenju nastane nevarno območje tudi za strojem."],"b2-verkehrseinweiser":["Kako je zavarovano premikanje med vožnjo, ko je vidljivost omejena?","Bager mora manevrirati za oviro.","Vozite, ne da bi videli signalne signale.","Po potrebi organizirajte ustrezna navodila z jasno komunikacijo.","Vzvratno vožnjo zavarujte le z enkratnim hupanjem.","Zmedene poti zahtevajo učinkovite ukrepe za preprečevanje trčenj in ukleščenj."],"b2-standplatz":["Kaj velja za stojalo bagra na pobočju?","Tla so nagnjena in so lahko spolzka.","Stroj se lahko iztegne, kolikor hoče, pri katerem koli naklonu.","Bager vedno postavite na rahlo plast zemlje.","Pred uporabo preverite stabilnost in meje delovanja stroja.","Naklon pobočja in podtalje pomembno vplivata na stabilnost."],"b2-oberleitung":["Zakaj je treba načrtovati oddaljenost nosilca od električnih vodov?","Roka se lahko pri obračanju približa kablu.","Električni preboj je možen tudi brez neposrednega kontakta.","Samo vedro lahko prevaja elektriko, ne pa tudi roka.","Pri suhi zemlji je vsaka razdalja samodejno varna.","Preden se približate električnim sistemom, je treba pojasniti omejitve uporabe in zaščitne razdalje."],"b2-fremdperson":["Mimoidoči vstopi na gradbišče v območju paniranja. Kaj je prav?","Oseba nenadoma stoji blizu žlice bagra.","Dvignite lopato in jo zavihtite nad osebo.","Takoj prenehajte z gibanjem in očistite območje.","Samo še naprej opazujte osebo skozi stransko okno.","Ljudje v nevarnem območju ne smejo biti ogroženi zaradi delovnih premikov."],"b2-parkstellung":["Kako je stroj za zemeljska dela zavarovan po končanem delu?","Bager ostane brez nadzora na gradbišču.","Pustite žlico na ravni glave.","Pustite motor delovati brez nadzora.","Odložite delovno opremo, zavarujte stroj in preprečite nepooblaščeno uporabo.","Pravilno parkiranje zmanjša nenamerno gibanje in nepooblaščen dostop."],"b2-eigenlast":["Zakaj so omejitve opreme ključne pri dvigovanju z bagrom?","Na roko je treba prevzeti težko breme.","V nasprotnem primeru sta lahko presežena stabilnost in dovoljena nosilnost.","Vsak stroj lahko dvigne kakršno koli breme, dokler se žlica prilega.","Samo dolžina vrvi zanke določa tveganje.","Informacije o dvigovanju in nosilnosti so odvisne od opreme in situacije uporabe."],"b2-untergrundhohlraum":["Tla nad staro kletjo so lahko votla. kaj počneš","Na to območje bi morali zapeljati bager.","Prečkajte mesto z največjim zagonom.","Pred nadaljevanjem vožnje razjasnite nosilnost in morebitne votline.","Preprosto postavite težko obremenitev na površino.","Votline se lahko zrušijo pod težo stroja in povzročijo zrušitev stroja."],"b2-feuchtigkeit":["Po močnem dežju se brežina zmehča. Kaj je prav?","Ob robu nasipa dela bager.","Premaknite stroj bližje robu, da povečate doseg.","Ignorirajte spremembe do konca izmene.","Ponovno ocenite pogoje tal in stabilnosti.","Vdor vlage lahko spremeni nosilnost in stabilnost nasipov."],"b2-bodenprobe":["Zakaj je treba pred izkopom preveriti načrte cevovoda?","Pod načrtovanim izkopom bi lahko potekali kabli.","Da je mogoče prepoznati linije in načrtovati ustrezne varnostne ukrepe.","Tako se lahko izkopavanje izvede hitreje, neodvisno od sistemov tretjih oseb.","Ker strojev nikoli ne smete uporabljati v bližini kablov.","Podzemni napajalni vodi zahtevajo zanesljivo razjasnitev lokacije pred izkopnimi deli."],"b2-maschinenzugang":["Kaj velja pri vstopanju in izstopanju iz stroja za zemeljska dela?","Stroj je na neravnem terenu.","Potisnite hidravlični vod navzdol iz kabine.","Uporabite predvidene stopnice in zagotovite varno podlago.","Med delovanjem stroja skočite na vrtljivo roko.","Varni vzponi in primerna mesta za ustavljanje zmanjšajo tveganje padcev in zmečkanin."],"b2-kupplung":["Kako preverite nov rovokopač po namestitvi?","Žlica je povezana preko hitre spojke.","Žlico ocenite le vizualno z večje razdalje.","Stopite neposredno pod dvignjeno žlico.","Zagotovite pravilno zaklepanje in predpisane krmilne korake.","Priključki, ki niso pravilno zaklenjeni, se lahko zrahljajo in ogrožajo ljudi."],"b2-hydraulikwartung":["Zakaj hidravličnih cevi ni dovoljeno odpreti pod pritiskom?","Zamenjati je treba cev.","Uhajajoča tekočina lahko povzroči resne poškodbe zaradi visokega tlaka.","Tlak vedno preprečuje iztekanje olja.","Odprto linijo lahko varno preverite z rokami.","Tekočina pod visokim pritiskom lahko prodre v tkivo in zahteva varno razbremenitev tlaka."],"b2-fahrweg":["Peljati se morate čez začasni gradbeni most. Kaj preverjate?","Most je zasnovan samo za določene obremenitve.","Ali se barva mostu ujema s strojem.","Nosilnost in primernost za težo in dimenzije stroja.","Le ali je po mostu že zapeljal lahek avto.","Začasni objekti se smejo uporabljati samo v okviru njihove dokazane nosilnosti."],"b2-baggertransport":["Kaj je pomembno pri transportu bagra na nizkem priklopniku?","Stroj se odpelje na naslednje gradbišče.","Pustite, da delovna oprema ohlapno štrli čez rob.","Med vožnjo naj bodo vrata kabine odprta.","Zavarujte stroj v skladu s transportnimi specifikacijami in preverite nakladalno opremo.","Transportne ključavnice in primerne nakladalne naprave preprečujejo zdrs in padec."],"b2-schaufelfuellung":["Zakaj nakladalec na kolesih ne sme voziti hitro z visoko dvignjeno žlico?","Tovor je težak in tla so neravna.","Visoko težišče lahko poveča tveganje prevrnitve in težave z vidljivostjo.","Žlica se samodejno stabilizira pri visokih hitrostih.","Višina lopate ni pomembna za stabilnost.","Dvignjeno težišče običajno poslabša stabilnost med vožnjo in zavijanjem."],"b2-fussgaenger":["Kako se obnašate, ko manevrirate poleg pešcev?","Dostop do gradbišča je tudi pešpot.","Z lopato usmerite pešce na stran.","Vožnjo izvajajte le, ko je območje varno prosto in obvladljivo.","Samo enkrat zatrobi in vozi počasi brez vidljivosti.","Promet vozil in potnikov morata biti učinkovito ločena ali varno usklajena."],"b2-ueberlastwarnung":["Pri dvigovanju stroj javi preobremenitev. kaj počneš","Dvignjeno breme doseže dovoljene meje.","Izklopite opozorilo in ga nespremenjeno dvigujte naprej.","Med delovanjem stroja nenadoma zategnite breme.","Ustavite nevarne premike in varno popravite stanje obremenitve.","Opozorila o preobremenitvi kažejo na morebitne kršitve omejitev in tveganja stabilnosti."],"b2-wasserleitung":["Med kopanjem se odkrije neznana cev. Kaj velja?","Proga ni prikazana v gradbenih načrtih.","Prenehajte z delom na prizadetem območju in naj linijo strokovno identificirajo.","Poskusite premakniti vrvico z lopato bagra.","Nadaljujte s kopanjem neposredno pod črto brez preverjanja.","Neznane napeljave lahko povzročijo električne, plinske ali vodne nevarnosti."],"b2-hangefahrt":["Kako voziš bager po strmem klancu?","Načrtovana trasa poteka po pobočju.","Vozite čez klanec ne glede na omejitve proizvajalca.","Upoštevajte dovoljeni naklon in predpisani način vožnje stroja.","Zavihajte roko daleč navzven, da uravnotežite vozilo.","Dovoljeni naklon je odvisen od stroja, površine in podatkov proizvajalca."],"b2-schlechtebeleuchtung":["Pri delu v temni jami je vidljivost neustrezna. Kaj je prav?","Skoraj ne vidite ljudi in ovir.","Povečajte hitrost kopanja, da hitro zaključite operacijo.","Ne uporabljajte luči, medtem ko motor deluje.","Prekinite delo, dokler nevarna območja niso dovolj vidna.","Za nadzorovano premikanje stroja je potrebna varna vidljivost voznega in delovnega območja."],"b2-kettenverschleiss":["Med dnevnim pregledom opazimo poškodovano gosenico. kaj počneš","Verižna povezava kaže očitno poškodbo.","Ne nadaljujte z nenadzorovano uporabo stroja in prijavite morebitno škodo.","Nadaljujte z vožnjo pri visoki hitrosti, da se veriga poravna.","Nadaljujte z delom samo na mehkih tleh brez preverjanja.","Poškodbe pogona lahko poslabšajo vodljivost in stabilnost."],"b2-ladearbeiten":["Z bagrom naložiš tovornjak. Kaj je pomembno?","Voznik tovornjaka ostane blizu nakladalnega prostora.","Zavihtite žlico nad nezaščiteno voznikovo kabino.","Preprečite zadrževanje ljudi v nevarnem območju in koordinirajte procese.","Začnite nakladati brez komunikacije z voznikom.","Pri nakladanju obstaja nevarnost padanja materiala in nihanja."],"b2-arbeitsunterbrechung":["Zaradi sestanka prekinete izkopavanje. Kaj velja?","Stroj naj stoji nekaj minut brez uporabe.","Dvignjeno lopato pustite kot oznako.","Pustite stroj brez nadzora z vključenim vlečnim pogonom.","Varno odložite stroj in ga zavarujte pred nenamerno uporabo.","Tudi kratke prekinitve zahtevajo varno stanje stroja."],"b2-rollmaterial":["Pri transportu z nakladalnikom na kolesih lahko razsuti material pade. Kaj je prav?","Nakladalec vozi blizu zaposlenih.","Varno poberite tovor in izberite varen način vožnje s primernim položajem lopate.","Dvignite lopato čim višje, da bo okolica dobro vidna.","Poberi tovor brez omejitve polnjenja žlice.","Razsuti tovori, visoki položaji žlic in slaba vidljivost lahko ogrožajo ljudi in promet."]};
